INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES
(170, 'koKR', 'Nowe zagrożenie', 'Mam nadzieję, że $gprzyszedłeś:przyszłaś; nam pomóc. Po ostatnim ataku troggów przyda się każda para rąk.$b$bSłyszałem, że te paskudy wyłażą spod ziemi w całej krainie, i wygląda na to, że Dolina Zimnej Grani nie jest wyjątkiem. Widziano je na wzgórzach na południowym wschodzie i przy zamarzniętym jeziorze.$b$bA to nie wszystko – ledwie kilka nocy temu napadły na nasz obóz na zachodzie i go zajęły!$b$bJest nas tu trochę za mało, $gchłopcze:dziewczyno;, a potrzeba silnych ramion, żeby odeprzeć troggi.', 'Balir Szronomłot chce, żebyś $gzabił:zabiła; 6 troggów twardopaszczych i 6 krzepkich troggów twardopaszczych.', '', 'Wróć do Balira Szronomłota w Dolinie Zimnej Grani w Dun Morogh.', '', '', '', '', 0),
(179, 'koKR', 'Krasnoludzkie wyposażenie', 'Cóż my tu mamy? Wyglądasz, jakby przydało ci się coś, co ogrzeje ci dłonie, hm?$b$bPowiem ci, co by pomogło: para porządnych, ciepłych rękawic. A że dobra ze mnie dusza, z przyjemnością dam ci odpowiednią parę. Mam jednak jeden warunek.$b$bPotrzebuję wilczego mięsa. Niezły układ, hm? Ty przyniesiesz mi trochę wilczego mięsa, a ja dopilnuję, żeby mróz nie odgryzł ci żadnego palca. No i co ty na to?', 'Sten Krzepkoręki chce dostać 8 kawałków twardego wilczego mięsa.', '', 'Wróć do Stena Krzepkorękiego w Dolinie Zimnej Grani w Dun Morogh.', '', '', '', '', 0),
(182, 'koKR', 'Jaskinia trolli', 'Razem z bratem, Senirem, zostaliśmy wysłani w różne części Dun Morogh, żeby zbadać zagrożenie ze strony trolli. Senat ma pełne ręce roboty z troggami, więc nie potrzebuje kolejnych utrapień.$b$bZ tego, co widziałem, trolle nie mają tu, w Dolinie Zimnej Grani, mocnej pozycji – siedzą głównie w południowej jaskini. Powiedziałbym, że armia nie będzie potrzebna. Kilka silnych ramion w zupełności wystarczy.$b$bMoże zechcesz pomóc w tym przedsięwzięciu? Jestem upoważniony, by wynagrodzić cię za pomoc.', 'Grelin Białobrody chce, żebyś $gzabił:zabiła; 10 młodych trolli Mroźnej Grzywy.', '', 'Wróć do Grelina Białobrodego w Dun Morogh.', '', '', '', '', 0),
(183, 'koKR', 'Łowca dzików', 'Nie ma to jak dzień polowania na dziki, co?$b$bTyle że tu, w Dolinie Zimnej Grani, dzików jest tyle, że prawie cała frajda przepada. Nie trzeba ich nawet prowokować do szarży. Same z siebie są rozjuszone i gotowe do ataku. Prawdę mówiąc, ostatnio namnożyło się ich w okolicy tyle, że moje codzienne polowania zrobiły się niebezpieczne.$b$bKrótko mówiąc, byłbym wdzięczny, gdybyś $gpomógł:pomogła; mi ubić kilka z nich.', 'Talin Bystrooki chce, żebyś $gzabił:zabiła; 12 małych dzików skalnych.', '', 'Wróć do Talina Bystrookiego w Dolinie Zimnej Grani w Dun Morogh.', '', '', '', '', 0),
(218, 'koKR', 'Skradziony dziennik', 'Mój dziennik! Zabrali go do jaskini. Ten, który go miał... To był wielki osiłek z dziwnymi znakami na skórze i twarzy. Nie zdążyłem mu się lepiej przyjrzeć.$b$bSkoro poszczęściło ci się z trollami, może odzyskasz go dla mnie?', 'Grelin Białobrody chce, żebyś $gzabił:zabiła; Grik\'nira Zimnego i $godzyskał:odzyskała; skradziony dziennik.', '', 'Wróć do Grelina Białobrodego w Dun Morogh.', '', '', '', '', 0),
(233, 'koKR', 'Poczta w Dolinie Zimnej Grani', 'Hm, pewnie nie masz ochoty wyświadczyć mi przysługi, $gchłopcze:dziewczyno;? Dziś przez przełęcz przyszedł plik listów, a ja nie mam czasu, żeby je dostarczyć.$b$bWszystkie są zaadresowane do Talina Bystrookiego. Znajdziesz go na zachodzie, dalej przy drodze. Rozbił obóz obok zamarzniętego jeziora.$b$bCo ty na to?', 'Dostarcz plik listów Talinowi Bystrookiemu w Dolinie Zimnej Grani.', '', '', '', '', '', '', 0),
(234, 'koKR', 'Poczta w Dolinie Zimnej Grani', 'Jeśli dobrze pamiętam, obóz Grelina jest dalej przy drodze, na południowym wschodzie. Na pewno nie może się doczekać swojej poczty.', 'Dostarcz list Grelinowi Białobrodemu w Dolinie Zimnej Grani.', '', '', '', '', '', '', 0),
(282, 'koKR', 'Obserwacje Senira', 'Zamierzałem wysłać raport do brata, Senira, przez mojego ucznia, ale czułbym się znacznie lepiej, gdyby trafił w bardziej... godne zaufania ręce. Oczywiście jeśli nie masz nic przeciwko?$b$bHmm... żeby dotrzeć do Kharanos, musisz przejść przez tunel.$b$bZanim wejdziesz do tunelu, porozmawiaj z górskim strażnikiem Thalosem. Tunel roi się teraz od troggów.$b$bWróć drogą do Kowadlina, a potem idź dalej na wschód, do tunelu. Thalos stacjonuje w pobliżu.', 'Porozmawiaj z górskim strażnikiem Thalosem.', '', '', '', '', '', '', 0),
(287, 'koKR', 'Warownia Mroźnych Grzyw', 'Zalegam z raportem i przydałaby mi się twoja pomoc, $n. Właśnie udało mi się ustalić, gdzie zaszyły się trolle, ale zobaczyłem ich tak wiele, że bałem się wejść do środka.$b$bOto czego potrzebuję... Zejdź do jaskini, rozejrzyj się w środku, zabij kilka trolli, a potem wróć tutaj.$b$bWyjdź z Kharanos drogą na północ, a kiedy dotrzesz do mostu, idź wzdłuż zamarzniętej rzeki na zachód, aż dojdziesz do Jeziora Lodowego Nurtu. Na zachodnim brzegu znajdziesz Wioskę Brewnallów. Warownia leży na południowy zachód od wioski.', 'Zbadaj Warownię Mroźnych Grzyw i zabij 5 łowców głów Mroźnej Grzywy dla Senira Białobrodego w Kharanos.', 'Zbadaj całą Warownię Mroźnych Grzyw', 'Wróć do Senira Białobrodego w Kharanos w Dun Morogh.', '', '', '', '', 0),
(291, 'koKR', 'Raporty', 'Doskonale! Zanieś mój raport senatorowi Barinowi Czerwonokamieniowi. To straszny ponurak, więc nie przejmuj się jego niezbyt słonecznym usposobieniem. Znajdziesz go w Żelaznej Kuźni, w komnacie, w której król Magni udziela audiencji.$b$bNie znasz drogi do Żelaznej Kuźni? Wyjdź z Kharanos drogą na północ, przejdź przez most, a potem idź drogą na wschód – po obu jej stronach stoją wielkie sztandary – w górę zbocza.$b$bA przy okazji, może lepiej nie wspominaj, jak mi $gpomogłeś:pomogłaś;? Nie mogą pomyśleć, że się tu obijam, rozumiesz?', 'Dostarcz raport Senira senatorowi Barinowi Czerwonokamieniowi w Żelaznej Kuźni.', '', '', '', '', '', '', 0),
(308, 'koKR', 'Odwracanie uwagi Jarvena', '', '', '', 'Wróć do Jarvena Gromowara w Dun Morogh.', '', '', '', '', 0),
(310, 'koKR', 'Zaciekli rywale', 'Muszę przyznać, że Gromowarowie robią dobre trunki. Ale muszą się nauczyć, że nie tylko ich piwo jest coś warte! Może pomożesz mi dać im tę nauczkę...$B$BMasz, weź tę beczkę Parzącego Jęczmiennego Browaru. Zakradnij się do piwnicy Gorzelni Gromowarów w Kharanos i podmień ją na jedną z ich beczek piwa gromu. Wtedy zobaczymy, czy ich goście nie wolą mojego trunku od ichniego!$B$BA jeśli ktoś pilnuje beczek, być może trzeba będzie odwrócić uwagę strażnika...', 'W piwnicy Gorzelni Gromowarów w Kharanos podmień beczkę piwa gromu na beczkę Parzącego Jęczmiennego Browaru.', '', '', '', '', '', '', 0),
(311, 'koKR', 'Powrót do Marleth', 'Podrzuciwszy beczkę Parzącego Browaru od Marleth do piwnicy gorzelni w Kharanos, zabierasz beczkę piwa gromu na dowód wykonanego zadania...', 'Zanieś beczkę piwa gromu Marleth Jęczmieniowar w Wiosce Brewnallów.', '', '', '', '', '', '', 0),
(312, 'koKR', 'Skradzione zapasy Tundry MacGranna', 'Miałem zapas suszonego mięsiwa na cały miesiąc, nasolonego i zamkniętego na zimę. Trzymałem je pod kluczem, żeby niedźwiedzie się do niego nie dobrały! Ale kiedy polowałem na jelenie, ta bestia, Stary Lodobrody, porwała mi całą spiżarnię. Przez torium się wprawdzie nie przebije, ale jeśli nie odzyskam mięsiwa, umrę z głodu.$b$bWyglądasz na kogoś, kto potrafi się skradać lepiej ode mnie. Może odzyskasz moje zapasy? Z tą moją chorą nogą nigdy nie zdążę wejść do tej jaskini i z niej wyjść.', 'Odzyskaj suszone mięsiwa Tundry MacGranna ze skradzionej spiżarni w jaskini Starego Lodobrodego.', '', 'Wróć do Tundry MacGranna w Wiosce Brewnallów w Dun Morogh.', '', '', '', '', 0),
(313, 'koKR', 'Siwa Nora', 'Prowadzenie machiny oblężniczej nie jest dla każdego. Trzeba mieć żelazny uścisk i stalowe nerwy... na szczęście mam jedno i drugie! A ty? Jak u ciebie z hartem ducha? Chcesz mi go udowodnić?$B$BOtóż... chcę, żeby w mojej machinie, Trollopługu, zrobiło się trochę przytulniej. Może przyniesiesz mi stos grzyw wendigo z Siwej Nory na zachód od Kharanos? Z tych grzyw wyjdzie świetny dywanik do wnętrza Trollopługu!', 'Zbierz 8 grzyw wendigo i zanieś je pilotowi Kamiennotrybowi.', '', 'Wróć do pilota Kamiennotryba w Składzie Steelgrilla w Dun Morogh.', '', '', '', '', 0),
(314, 'koKR', 'W obronie stada', 'W środku nocy usłyszeliśmy krzyki. A rano, jak można się było spodziewać, ze stada zniknęły dwa barany. Ta podła bestia zwana Vagashem poluje na nasze źródło utrzymania. Większość armii króla Magniego walczy w dalekich krainach u boku Przymierza, więc nie ma komu trzymać Vagasha na dystans.$b$bMoże starczy ci odwagi, by wytropić tę bestię i ją zabić. Przynieś mi jeden z jego kłów, a cię wynagrodzę. Vagash czai się tuż nad ranczem, ale strzeż się – to śmiertelnie groźny zwierz.', 'Rudra Amberstill chce, żebyś $gzabił:zabiła; Vagasha i $gprzyniósł:przyniosła; jego kieł na jej ranczo baranów.', '', 'Wróć do Rudry Amberstill w Dun Morogh.', '', '', '', '', 0),
(315, 'koKR', 'Idealny stout', 'Mam misję – misję stworzenia idealnego stouta. Wiem, że mi się uda – warzenie mam we krwi. Muszę tylko znaleźć właściwy przepis...$B$BTrolle Mroźnej Grzywy uprawiają roślinę, połyskliwe ziele, wysoko na wzgórzach na wschodzie. Używają jej w swoich dziwnych plemiennych rytuałach. My, krasnoludy, nie znaleźliśmy dla niej większego zastosowania, ale ma wyjątkowy smak... i chcę z nią poeksperymentować w moich trunkach!$B$BZdobądź dla mnie trochę połyskliwego ziela od jasnowidzów Mroźnej Grzywy albo podwędź je z trollowych koszy na ziele.', 'Przynieś 6 pęków połyskliwego ziela Rejoldowi Jęczmieniowarowi w Wiosce Brewnallów.', '', 'Wróć do Rejolda Jęczmieniowara w Dolinie Chłodnej Bryzy w Dun Morogh.', '', '', '', '', 0),
(317, 'koKR', 'Zapasy dla Parolotu', 'Szykuję się do misji dla Brygady Oblężniczej. To długa wyprawa i muszę zaopatrzyć Parolot w zapasy na cały miesiąc. Może, zanim Steelgrill skończy pracę nad moim czołgiem, zapolujesz trochę dla mnie?$B$BPotrzebuję futer na posłanie i dziczyzny do jedzenia. Mięso zdobędziesz z dzików, a futra z niedźwiedzi... jedne i drugie znajdziesz na śnieżnych polach na południe od Siwej Nory.', 'Zbierz 4 kawały dziczyzny i 2 gęste niedźwiedzie futra i dostarcz je pilotowi Bellowfizowi w Składzie Steelgrilla.', '', 'Wróć do pilota Bellowfiza w Składzie Steelgrilla w Dun Morogh.', '', '', '', '', 0),
(318, 'koKR', '„Wieczny blask”', 'Rejold Jęczmieniowar eksperymentuje ze swoimi trunkami. Niektóre są smaczne, niektóre paskudne, a niektóre... cóż, niektóre powalą każdego krasnoluda poza najtęższymi.$B$BMieszka w Wiosce Brewnallów na zachód od Kharanos, a jeden z jego trunków, „Wieczny blask”, to właśnie to, czego mi trzeba. Rozgrzeje mnie w zimnej drodze.$B$BA do tego... to błogosławione paliwo pali się tak gorąco, że mogę wlać je do pieca Parolotu i dostać zastrzyk mocy! Ta mała sztuczka nieraz wyciągnęła mnie z tarapatów.', 'Zdobądź baryłkę „Wiecznego blasku” od Rejolda Jęczmieniowara w Wiosce Brewnallów.', '', '', '', '', '', '', 0),
(319, 'koKR', 'Przysługa za „Wieczny blask”', 'Mam pod ręką baryłkę „Wiecznego blasku”, ale... wyświadczysz mi przysługę? Wiosce Brewnallów przydałaby się pomoc przeciwko dzikim zwierzętom, które krążą po okolicznych śniegach. Czasem podchodzą całkiem blisko.$B$BNie boimy się tych niedźwiedzi, kotów i dzików – żaden szanujący się krasnolud by się nie bał – ale jeśli się nimi zajmiesz, będziemy mieli więcej czasu na nasze rzemiosło i warzenie.', 'Zabij 6 lodopazurych niedźwiedzi, 8 starych dzików skalnych i 8 lampartów śnieżnych, a następnie wróć do Rejolda Jęczmieniowara w Wiosce Brewnallów.', '', 'Wróć do Rejolda Jęczmieniowara w Dolinie Chłodnej Bryzy w Dun Morogh.', '', '', '', '', 0),
(320, 'koKR', 'Powrót do Bellowfiza', 'Oto twoja baryłka „Wiecznego blasku”, $N. I jeszcze raz dziękuję za wcześniejsze polowanie.', 'Oddaj baryłkę „Wiecznego blasku” pilotowi Bellowfizowi w Składzie Steelgrilla.', '', '', '', '', '', '', 0),
(384, 'koKR', 'Żeberka z dzika w piwie', 'Nic tak nie cieszy gości mojej karczmy jak żeberka z dzika w piwie! Jest tylko jeden kłopot: miejscowy traper, który przynosił mi zaopatrzenie, zaciągnął się do armii króla, żeby walczyć na froncie Przymierza.$b$bMoże mi pomożesz? Jeśli przyniesiesz mi sześć żeber dzika skalnego i słód „Rapsodia” z tutejszej karczmy, dam ci rodzinny przepis na moje słynne żeberka z dzika w piwie, nie mówiąc już o darmowej próbce! Cały sekret tkwi w słodzie!', 'Ragnar Gromowar z Kharanos chce dostać 6 żeber dzika skalnego i kufel słodu „Rapsodia”.', '', 'Wróć do Ragnara Gromowara na Migoczącej Grani w Dun Morogh.', '', '', '', '', 0),
(400, 'koKR', 'Narzędzia dla Steelgrilla', 'Beldin Steelgrill prowadzi tutejszy warsztat mechaniczny i nie ma lepszego fachowca od machin oblężniczych! Tyle że nie oszczędza narzędzi. Słowo daję, psuje więcej kluczy łukowych, niż jesteśmy w stanie mu dostarczyć!$B$BWłaśnie skompletowaliśmy jego ostatnie zamówienie na narzędzia. Jeśli mu je zaniesiesz, na pewno ci się to opłaci.$B$BJego warsztat, Skład Steelgrilla, jest tuż na północny wschód od Kharanos. Chętnie przesiadują tam weterani, piloci machin oblężniczych, więc miej uszy otwarte na okazje, kiedy tam będziesz.', 'Dostarcz narzędzia Steelgrilla Beldinowi Steelgrillowi.', '', '', '', '', '', '', 0),
(403, 'koKR', 'Strzeżona beczka Gromowarów', '', '', '', '', '', '', '', '', 0),
(412, 'koKR', 'Operacja Rekombobulacja', 'Po dalszej analizie sytuacji w Gnomoregan okazuje się, że nie tylko nie zdołaliśmy wytępić troggów, ale przy okazji zamieniliśmy większość gnomiej rasy w potworne, bezmyślne i złośliwe trędowate gnomy.$b$bOzzie i ja zamierzamy odwrócić ten okropny trąd za pomocą naszego najnowszego wynalazku: Rekombobulatora. Maszyna jest prawie gotowa, ale rozpaczliwie potrzebujemy trybików restabilizacyjnych i żyromechanicznych zębatek. Zdobądź je dla nas od trędowatych gnomów przed wejściem do Gnomoregan.', 'Przynieś Razzle\'owi Żwawotrybowi w Kharanos 8 trybików restabilizacyjnych i 8 żyromechanicznych zębatek.', '', 'Wróć do Razzle\'a Żwawotryba w Dun Morogh.', '', '', '', '', 0),
(413, 'koKR', 'Połyskliwy stout', 'Chciałbym, żeby mój brat Wellart spróbował mojego nowego połyskliwego stouta. Jest górskim strażnikiem i stacjonuje w południowej wieży strażniczej, jednej z dwóch wież na granicy z Loch Modan.$B$BMoże i nie jest piwowarem jak reszta nas, Jęczmieniowarów, ale uwielbia dobre trunki i wiem, że ten mu zasmakuje.$B$BZaniesiesz mu ode mnie tę beczkę połyskliwego stouta?', 'Zanieś beczkę połyskliwego stouta górskiemu strażnikowi Jęczmieniowarowi.', '', '', '', '', '', '', 0),
(414, 'koKR', 'Stout dla Kadrella', 'Piłem jeszcze tego połyskliwego stouta, którego zrobił mój brat – świetny trunek! Chcę, żeby spróbował go jakiś inny górski strażnik. Nazywa się Kadrell i zwykle patroluje drogę przez Thelsamar w Loch Modan.$B$BŻeby dostać się do Thelsamaru, idź na południowy wschód przez tunel, a kiedy ścieżka przejdzie w rozwidloną drogę, skręć na północny wschód. Idź tą drogą prosto do Thelsamaru.$B$BDaj górskiemu strażnikowi Kadrellowi tę baryłkę połyskliwego stouta i zobacz, co powie!', 'Zanieś baryłkę połyskliwego stouta górskiemu strażnikowi Kadrellowi w Loch Modan.', '', '', '', '', '', '', 0),
(415, 'koKR', 'Nowy trunek Rejolda', 'Rejold Jęczmieniowar z Wioski Brewnallów o ciebie pytał.$B$BChce z tobą porozmawiać o nowym trunku, który warzy... wspominał, że mu przy nim $gpomogłeś:pomogłaś;. Może warto wrócić do Wioski Brewnallów i posłuchać, co ma do powiedzenia.$B$BMoże skapnie ci z tego jakiś darmowy trunek...', 'Porozmawiaj z Rejoldem Jęczmieniowarem.', '', '', '', '', '', '', 0),
(417, 'koKR', 'Zemsta pilota', 'Hildelve zapisał w dzienniku, że zaatakował go Parchopazur, „ogromny lodopazury niedźwiedź”. Przepędził bestię, ale wcześniej zdążyła go ona dotkliwie poszarpać.$B$BSądząc po stanie ciała Hildelve, Parchopazur musiał później wrócić i go zabić.$B$BW dzienniku Hildelve zapisał jednak swoje jedno, ostatnie życzenie:$B$BZemstę na Parchopazurze.', 'Zabij Parchopazura.$B$BZanieś jego parszywy pazur i dziennik Hildelve pilotowi Młotostopemu.', '', 'Wróć do pilota Młotostopego w Posterunku Północnej Bramy w Dun Morogh.', '', '', '', '', 0),
(419, 'koKR', 'Zaginiony pilot', 'Mój przyjaciel, pilot machiny oblężniczej jak ja, Mori Hildelve, zaginął w górach. Szukaliśmy rzadkiej rudy potrzebnej do wyrobu prochu wysokiej jakości i podczas poszukiwań wjechał swoją machiną na strome wzgórze i ją rozwalił!$B$BWciąż przekonany, że ruda jest gdzieś w tych górach, Hildelve kazał mi pilnować naszych machin, a sam ruszył dalej pieszo na poszukiwania.$B$BMinęło już kilka dni, a nocami słyszę na wzgórzach zwierzęce ryki. Mori to twardziel, ale się martwię.$B$BProszę cię, $N. Znajdź go.', 'Odnajdź pilota Hildelve.', '', '', '', '', '', '', 0),
(420, 'koKR', 'Obserwacje Senira', 'Troggi w tunelu są wyjątkowo wrogie i bez wahania atakują podróżnych. Ale wyglądasz na $gtwardego:twardą;, więc pewnie nic ci nie grozi.$b$bWskazówki? Jeśli chcesz porozmawiać z Senirem, znajdziesz go w Kharanos.$b$bPrzejdź przez tunel, a kiedy wyjdziesz po drugiej stronie, idź po prostu dalej drogą – zaprowadzi cię prosto do Kharanos.', 'Dostarcz raport Grelina Senirowi Białobrodemu w Kharanos.', '', '', '', '', '', '', 0),
(432, 'koKR', 'Przeklęte troggi!', 'Niech Światłość pokarze te troggi – zamieniły mój plac budowy w ruinę! Spójrz tylko, znowu poszła beczka prochu!$b$bOch, chciałbym tam zejść i poukręcać im te chude karki, jednemu po drugim! Chcę je wszystkie wybić!$b$bTo nie może być dobre dla mojego zdrowia, cały ten stres i złość... Co mi zostawiły? Nic!$b$bSam bym je pozabijał, ale nie mam już dobrego oka! Idź do kamieniołomu i zabij kilka tych plugawych paskud! Zapłacę ci! Tylko je pokiereszuj, pozabijaj!', 'Zabij 6 czaszkotłuków twardopaszczych dla brygadzisty Kamiennobrewego w Kamieniołomie Gol\'Bolar.', '', 'Wróć do brygadzisty Kamiennobrewego w Dun Morogh.', '', '', '', '', 0),
(433, 'koKR', 'Sługa narodu', 'Jako członek Senatu i Ligi Odkrywców wziąłem na siebie rozprawienie się z tą częścią plagi troggów, która opanowała nasze ziemie.$b$bZ pewnością narobiły bałaganu w Kamieniołomie Gol\'Bolar, i to bez żadnego powodu. Kiedy wkopaliśmy się głęboko w ziemię, wylały się stamtąd, niszcząc nasz sprzęt i przepędzając górników. Nie pozostaje nam nic innego, jak wytępić je wszystkie, odbudować, co trzeba, i wrócić do pracy.$b$bJeśli pomożesz mi z troggami, chętnie wynagrodzę ci poświęcony czas.', 'Zabij 10 kościołamów twardopaszczych dla senatora Mehra Kamiennokotlina w Kamieniołomie Gol\'Bolar.', '', 'Wróć do senatora Mehra Kamiennokotlina w Dun Morogh.', '', '', '', '', 0),
(466, 'koKR', 'Poszukiwanie incendycytu', 'Słyszałem, że na Bagniskach, w jaskini na północny zachód od Bramy Algaz, znaleziono rzadką rudę – incendycyt. To niestabilne świństwo i trudno go używać tak, żeby nie wysadzić się w powietrze, ale jestem pewien, że jeśli wytopi się go jak należy, wyjdą z niego pociski armatnie o potężnej sile rażenia!$B$BZdobądź dla mnie rudę incendycytu, a ja znajdę kogoś na tyle odważnego, żeby z nią poeksperymentował.$B$BA, i żeby wydobyć tę rudę z żyły, musisz znać się na górnictwie. Jeśli się nie znasz, to... zabierz do tej jaskini przyjaciela, który się zna!', 'Przynieś 6 porcji rudy incendycytu pilotowi Kamiennotrybowi w Dun Morogh.', '', 'Wróć do pilota Kamiennotryba w Składzie Steelgrilla w Dun Morogh.', '', '', '', '', 0),
(467, 'koKR', 'Poszukiwania Kamiennotryba', 'Pilot Kamiennotryb kocha swoją machinę oblężniczą, jak każdy pilot powinien! I zawsze szuka nowych sposobów, by zwiększyć siłę ognia swojego czołgu!$B$BDoszły go plotki o rzadkiej rudzie i szuka kogoś, kto ją dla niego wytropi. Jeśli nogi same rwą ci się do drogi, odszukaj Kamiennotryba w Składzie Steelgrilla w Dun Morogh i dowiedz się, czego chce.', 'Porozmawiaj z pilotem Kamiennotrybem.', '', '', '', '', '', '', 0),
(1679, 'koKR', 'Muren Gromdarda', 'Witaj, $gwojowniku:wojowniczko;! Dobrze się zapowiadasz, ale musisz jeszcze poznać kilka sztuczek, a Muren Gromdarda to właśnie krasnolud, który cię ich nauczy.$B$BMurena znajdziesz w Sali Oręża w Dzielnicy Wojskowej Żelaznej Kuźni. Porozmawiaj z nim, kiedy będziesz $ggotów:gotowa; się dowiedzieć, co znaczy być wojownikiem.', 'Porozmawiaj z Murenem Gromdardą.', '', '', '', '', '', '', 0),
(1783, 'koKR', '', 'Szpiegowaliśmy krasnoludy z klanu Czarnorytych, co się okopały na południe od Jeziora Łoża Helma. Wiedzieliśmy, że nic dobrego nie knują, więc Narm i ja postanowiliśmy przyjrzeć się z bliska – i widzieliśmy, jak ich przywódca wydaje rozkazy paru swoim ludziom.$B$BNarm i ja skorzystaliśmy z okazji i ubiliśmy kilku, ale okazali się twardsi, niż myśleliśmy, a potem następni zaszli nas znienacka. Narm kazał mi uciekać i sprowadzić pomoc, no to jestem.$B$BNarm potrzebuje pomocy i nie spocznę, póki jej nie dostanie.$B$BPomożesz, co, $N?', 'Weź Symbol Życia i wskrześ Narma Faulka w Dun Morogh.', '', '', '', '', '', '', 0),
(1784, 'koKR', '', 'Zanim padłem w walce, Muiredon i ja prawie pokonaliśmy jednego ze szpiegów Czarnorytych przy tamtym domku. Widzieliśmy, jak ich kapitan przekazuje im rozkazy, i chcieliśmy go zabić i przejąć te rozkazy.$B$BNiektórzy członkowie rady w Żelaznej Kuźni wciąż nie wierzą, że w Dun Morogh są krasnoludy z klanu Czarnorytych. Jeśli zdobędziemy jedno z tych pism, nie tylko będziemy mieli dowód na ich poczynania, ale być może dowiemy się też, co planują.$B$BZdobądź jedno z tych pism i zanieś je Muiredonowi, $N.', 'Zdobądź pismo Czarnorytych od krasnoludów z klanu Czarnorytych nad Jeziorem Łoża Helma i wróć do Muiredona Bojokucia w Żelaznej Kuźni.', '', 'Wróć do Muiredona Bojokucia w Dun Morogh.', '', '', '', '', 0),
(1879, 'koKR', 'Porozmawiaj z Bink', '$N! Bink, moja gnomia koleżanka z Żelaznej Kuźni, przesyła wieści. Ma zadanie do wykonania i nie powierzy go nikomu poza magiem! Czy to właśnie ty, $N?$B$BJeśli tak, porozmawiaj z Bink. Spędza czas w Sali Tajemnic w Dzielnicy Mistycznej Żelaznej Kuźni.', 'Porozmawiaj z Bink w Żelaznej Kuźni.', '', '', '', '', '', '', 0),
(2160, 'koKR', 'Zapasy dla Tannoka', 'Hej! Wyglądasz na $gdzielnego poszukiwacza:dzielną poszukiwaczkę; przygód. Jeśli zamierzasz stawić czoła przełęczy, może zaniesiesz paczkę do karczmy w Kharanos?$b$bPrzecież i tak zatrzymasz się w karczmie, prawda? Jeśli przedostaniesz się przez przełęcz, na pewno zechcesz tam złapać oddech.$b$bTak czy siak, zanieś to Tannokowi Szronomłotowi, pomocnikowi karczmarza. Sam nie przejdę przez przełęcz, a eskorta górskich strażników pojawi się tu dopiero za kilka dni!', 'Dostarcz skrzynkę zapasów dla karczmy Tannokowi Szronomłotowi w Kharanos.', '', '', '', '', '', '', 0),
(2218, 'koKR', 'Droga do zbawienia', 'Kolejna zagubiona dusza szuka przewodnictwa, co? Pewnie chcesz odnaleźć cel – swój cel. Widziałem to tysiąc razy: kolejny bohater szuka roboty.$B$BCóż, to twój szczęśliwy dzień, $gprzyjacielu:przyjaciółko;. Hogral ma lekarstwo na twoją przypadłość.$B$BZrobisz tak: idź tą drogą w górę do Żelaznej Kuźni i dotrzyj do Opuszczonej Pieczary. Tam znajdź gildię złodziei i porozmawiaj z Hulfdanem Czarnobrodym. On wprowadzi cię na drogę do zbawienia.$B', 'Porozmawiaj z Hulfdanem Czarnobrodym w Żelaznej Kuźni.', '', '', '', '', '', '', 0),
(2238, 'koKR', 'Proste krętactwa', 'Widzisz, król rozkopuje kamieniołom w poszukiwaniu rudy i klejnotów. To więcej bogactw, niż jakikolwiek krasnolud powinien zobaczyć przez dziesięć żywotów.$B$BUkryty Krąg ma swoje wartości, $N. A najbardziej cenimy kosztowności. Łapiesz?$B$BOtóż uważamy, że król powinien podzielić się częścią tych łupów, ale nie chcemy, żeby stary „Smrodobrody” wiedział, że się dzieli – jeśli wiesz, o czym mówię.$B$BMusisz porozmawiać z Oninem MacHammarem koło Gnomoregan i przynieść nam raport. Ten cwany krasnolud ukrył się wśród trędowatych. Uważaj na siebie.', 'Odnajdź Onina MacHammara koło Gnomoregan.', '', '', '', '', '', '', 0),
(2239, 'koKR', 'Raport Onina', 'Kamieniołom? Ano, te potworne opancerzone czołgi parowe przejeżdżają obok tego posterunku niemal codziennie.$B$BMoi informatorzy na wschodzie mówią, że czołg wyrusza z Żelaznej Kuźni, zabiera ładunek w Kamieniołomie Gol\'Bolar, zatrzymuje się w Kharanos, żeby uzupełnić paliwo, a potem z jakiegoś przeklętego powodu jedzie okrężną drogą obok Gnomoregan, zanim dotrze do Żelaznej Kuźni, gdzie zostawia ładunek.$B$BWszystko jest w raporcie. Zanieś go Hulfdanowi, żeby mógł zaplanować następny krok.$B', 'Zanieś raport Onina Hulfdanowi w Żelaznej Kuźni.', '', '', '', '', '', '', 0),
(2299, 'koKR', 'Do Hulfdana!', 'Gdzie się $gpodziewałeś:podziewałaś;, $N? Hulfdan wszędzie cię szuka. Myśleliśmy, że król zakuł cię w kajdany.$B$BRuszaj jak najszybciej do Żelaznej Kuźni i porozmawiaj z Hulfdanem!', 'Udaj się do Żelaznej Kuźni i porozmawiaj z Hulfdanem Czarnobrodym.', '', '', '', '', '', '', 0),
(2841, 'koKR', 'Wojny machin', 'Gnomia technologia – dwa lata temu służyła głównie za puentę dowcipów. Czasy się jednak zmieniły. Teraz zbudowali nową machinę, która jest lepsza od wszystkich naszych modeli rozdrabniaczy razem wziętych. Potrzebuję tych planów, $N!$B$BNiestety, plany są zamknięte w sejfie w pobliżu mechinżyniera Termowtyka. Co gorsza, szyfr do sejfu zna tylko mechinżynier Termowtyk.$B$BZrób wszystko, co trzeba, żeby zdobyć ten szyfr, $N. Potem otwórz sejf i przynieś mi te plany!$B', 'Zdobądź plany machiny i szyfr do sejfu Termowtyka w Gnomoregan i zanieś je Noggowi w Orgrimmarze.$B', '', 'Wróć do Nogga w Orgrimmarze.', '', '', '', '', 0),
(2842, 'koKR', 'Główny inżynier Scooty', 'Gdy tylko Kernobee dał nam znać o nowej gnomiej machinie, Scooty i ja zabraliśmy się do pracy nad Transpoliporterem 6000: najszybszym i najbardziej niezawodnym sposobem, by dostać się do Gnomoregan.$B$BW końcu jest gotów przyjąć pasażerów, $N. Jeśli chcesz go wypróbować, udaj się do Łupieżczej Zatoki i porozmawiaj ze Scootym przy lądowisku wiatrojeźdźców. Do Łupieżczej Zatoki dotrzesz statkiem z Zapadki.$B$BOczywiście zawsze możesz spróbować przedrzeć się do Gnomoregan przez roiące się od krasnoludów góry Dun Morogh!', 'Porozmawiaj ze Scootym w Łupieżczej Zatoce.', '', '', '', '', '', '', 0),
(2843, 'koKR', 'Do Gnomoregaaaaan!', 'Dopóki masz przy sobie transponder, wystarczy, że wejdziesz na platformę, a teleport przeniesie cię prosto do Gnomoregan.$B$BMogą wystąpić pewne nietypowe skutki uboczne, ale żaden z nich nie powinien być trwały... już nie.$B$BO mało nie zapomniałem o najważniejszym – o powrocie. Kiedy zechcesz wrócić, po prostu wejdź na platformę transpoliportera w Gnomoregan!$B$BA teraz skalibruję transponder do twojego wzrostu i wagi.$B', 'Zaczekaj, aż Scooty skalibruje gobliński transponder.', 'Gobliński transponder', 'Wróć do Scooty\'ego w Łupieżczej Zatoce w Dolinie Cierniodławów.', '', '', '', '', 0),
(2904, 'koKR', 'Niezły bigos', '<Kernobee jęczy.> Co... Co się stało?$B$BOstatnie, co pamiętam, to jak pojmała mnie banda Czarnorytych, stłukli mnie prawie na śmierć, a potem wrzucili tutaj, do tych obmierzłych troggów.$B$BWyciągnij mnie stąd, $N!$B$BPlan jest taki: zaprowadź mnie do wyjścia. Jeśli wyjdziemy z tego cało, udasz się do Łupieżczej Zatoki i dasz znać Scooty\'emu, że poszedłem do Zapadki ostrzec Majsterkowicza, że Czarnoryci maczali palce w budowie tej supermachiny.$B$BRuszajmy!', 'Odeskortuj Kernobee do wyjścia z Mechanicznego Korytarza, a następnie zdaj raport Scooty\'emu w Łupieżczej Zatoce.', 'Ratunek dla Kernobee', 'Wróć do Scooty\'ego w Łupieżczej Zatoce w Dolinie Cierniodławów.', '', '', '', '', 0),
(2922, 'koKR', 'Ratuj mózg Techbota!', 'Kiedy upadło nasze ukochane Gnomoregan, jakaś zabłąkana iskra musiała porazić moje biedne dzieło, Techbota. Kiedyś pomagał mnie i moim wspólnikom dzięki niezliczonym gadżetom i nieograniczonemu zasobowi wiedzy, ale jego pozytroniczny mózg uległ polaryzacji. Teraz jest negatroniczny... i Techbot zachowuje się dokładnie na odwrót. Włóczy się w szale po Gnomoregan!$B$BAle może da się go jeszcze uratować. Może jeśli zdobędziesz rdzeń pamięci Techbota i mi go przyniesiesz, odkryję przyczynę polaryzacji i naprawię mojego biednego Techbota.$B$B', 'Przynieś rdzeń pamięci Techbota Nadiskrownikowi Opiłkowi w Żelaznej Kuźni.', '', 'Wróć do Nadiskrownika Opiłka w Majsterkowie w Żelaznej Kuźni.', '', '', '', '', 0),
(2924, 'koKR', 'Sztuczne esencje', 'Niemal uniwersalny element mechaniczny – sztuczna esencja – bardzo przydawał się majstrom i kowalom z Gnomoregan. Ale podczas gorączkowej ucieczki z naszego miasta nikt nie pomyślał, żeby zabrać choć jedno z tych urządzeń! A ja potrzebuję ich całego zapasu do prac, które wkrótce rozpocznę.$B$BProszę, wejdź do Gnomoregan i zdobądź dla mnie trochę sztucznych esencji. Znajdziesz je w głębszych częściach naszego miasta, w pojemnikach zwanych ekstrapolatorami sztuczności.$B$BDziękuję, $N, i proszę, pospiesz się!', 'Przynieś 12 sztucznych esencji Klockmortowi Kluczokrętowi w Żelaznej Kuźni.', '', 'Wróć do Klockmorta Kluczokręta w Majsterkowie w Żelaznej Kuźni.', '', '', '', '', 0),
(2925, 'koKR', 'Niezbędnik Klockmorta', 'Mój przyjaciel gnom, Klockmort Kluczokręt, przysłał mi wieści z Żelaznej Kuźni. Pisze, że potrzebuje pomocy w niebezpiecznej, ale niezbędnej wyprawie do Gnomoregan – niegdyś wspaniałego miasta gnomów, dziś skażonego i pełnego oszalałych gnomów i ich machin.$B$BMuszę zostać tutaj, ale serce mi się kraje, że nie mogę pomóc przyjacielowi. Jeśli pójdziesz w moim zastępstwie, będę twoim dłużnikiem.$B$BKlockmorta znajdziesz w Majsterkowie, w Żelaznej Kuźni.', 'Porozmawiaj z Klockmortem Kluczokrętem w Żelaznej Kuźni.', '', '', '', '', '', '', 0),
(2926, 'koKR', 'Gnomokaina', 'Od czasu wypadku Gnoarn myśli i mówi tylko o tym, żeby oczyścić Gnomoregan z plagi troggów i znaleźć lekarstwo na chorobę, która je trawi, $N.$B$BNa szczęście Razzle i ja jesteśmy bliscy wynalezienia jakiegoś lekarstwa – albo przepisu na naprawdę mocny rum. Nie dowiemy się, dopóki nie sprawdzimy! Oczywiście, żeby sprawdzić naszą teorię, będziemy potrzebowali paru rzeczy, a konkretnie opadu z napromieniowanych troggów w Gnomoregan. Napełnij tę fiolkę zieloną poświatą i przynieś ją z powrotem!', 'Użyj pustej ołowianej fiolki na próbki na napromieniowanych najeźdźcach lub napromieniowanych łupieżcach, aby zebrać radioaktywny opad. Gdy fiolka się napełni, zanieś ją Ozziemu Pstrykowoltowi w Kharanos.', '', 'Wróć do Ozziego Pstrykowolta w Kharanos w Dun Morogh.', '', '', '', '', 0),
(2927, 'koKR', 'Nazajutrz', 'Chyba nie myślisz, że zawsze byłem łysy? Skądże, $gpanie:pani;! To przez wyciek promieniowania w Gnomoregan spotkała mnie ta tragiczna utrata włosów. Przed tamtym dniem miałem jedyne gnomie afro w całym Azeroth.$B$B<Gnoarn wygraża pięścią w powietrzu.>$B$BNiech szlag trafi te przeklęte, plugawe troggi – niech szlag trafi je wszystkie!!$B$BMoże jeszcze nie jest za późno, $N. Może da się je jeszcze uratować – to znaczy miasto! Porozmawiaj z Ozziem Pstrykowoltem w Kharanos. On i jego wspólnik Razzle pracują nad rozwiązaniem.', 'Porozmawiaj z Ozziem Pstrykowoltem w Kharanos w Dun Morogh.', '', '', '', '', '', '', 0),
(2929, 'koKR', 'Wielka zdrada', 'Ufałem Termowtykowi. Nigdy nie przypuszczałem, że zdradzi mnie i cały gnomi lud. I po co? Dla władzy? Bogactwa? Wszystko to z czasem by zdobył. Teraz wypędzono nas z naszego domu, a rządzi nim ten szaleniec. Król niczego...$B$BOdbijemy Gnomoregan, $N. Nie spoczniemy, dopóki miasto nie wróci w nasze ręce. Jeśli chcesz przyłączyć się do naszej walki, proszę cię o jedną prostą rzecz: zabij zdrajcę. Zniszcz mechinżyniera Termowtyka.', 'Wyrusz do Gnomoregan i zabij mechinżyniera Termowtyka. Po wykonaniu zadania wróć do Wielkiego Majstra Mekanownika.', '', 'Wróć do Wielkiego Majstra Mekanownika w Majsterkowie w Żelaznej Kuźni.', '', '', '', '', 0),
(2930, 'koKR', 'Ratowanie danych', 'Kiedy uciekaliśmy z Gnomoregan, zostawiliśmy tyle danych! Niezwykle ważnych danych!$B$BPotrzebuję danych z pryzmatycznej karty perforowanej, z terminalu o wysokim poziomie zabezpieczeń – matrycowego perforografu 3005-D – głęboko w Gnomoregan. Musisz dostać się do terminalu, ale najpierw potrzebujesz uprawnień... a żeby je zdobyć, musisz skorzystać z terminali o niższym poziomie zabezpieczeń – modeli -A, -B i -C. A do TEGO potrzebne są karty perforowane dostępu, poczynając od białej... a wszystkie karty perforowane zostawiliśmy w mieście.$B$BTo katastrofa! Pomożesz?', 'Przynieś pryzmatyczną kartę perforowaną mistrzowi mechanikowi Odleworurowi w Żelaznej Kuźni.', '', 'Wróć do mistrza mechanika Odleworura w Majsterkowie w Żelaznej Kuźni.', '', '', '', '', 0),
(2931, 'koKR', 'Zadanie Odleworura', 'Mistrz mechanik Odleworur z Żelaznej Kuźni potrzebuje śmiałków! Organizuje oddziały, które mają wrócić do Gnomoregan po dane – to misja najwyższej wagi i ściśle tajna.$B$BOdleworur może i nie należy, tak jak ja, do Oświeconego Zgromadzenia Nauk Arkanologicznych, Alchemicznych i Inżynieryjnych, ale to i tak bystry gnom, więc jeśli uważa, że to ważne, to według moich obliczeń istnieje osiemdziesiąt cztery procent prawdopodobieństwa, że rzeczywiście jest ważne!$B$BTo niezłe szanse!', 'Porozmawiaj z mistrzem mechanikiem Odleworurem w Żelaznej Kuźni.', '', '', '', '', '', '', 0),
(2945, 'koKR', 'Pierścień pokryty brudem', 'Przy zwłokach jednego z Czarnorytych $gznalazłeś:znalazłaś; coś, co wygląda na pierścień. Trudno jednak powiedzieć, co to za pierścień: brud i zaschnięty osad całkowicie go oblepiają, więc nie da się go nosić. Wydaje ci się, że pod osadem dostrzegasz delikatny połysk szlachetnego metalu, a może nawet błysk klejnotu.$B$BJeśli chcesz zrobić z niego użytek, musisz znaleźć coś, czym usuniesz z niego zaschnięty osad.', 'Znajdź sposób na usunięcie brudu z pierścienia pokrytego brudem.', '', '', '', '', '', '', 0),
(2947, 'koKR', 'Powrót pierścienia', 'Po otwarciu pudełka, które wypluł Błyskomat 5200, znajdujesz to, czego się $gspodziewałeś:spodziewałaś; – lśniący pierścień! Gdy go zakładasz, czujesz, jak przez twoje ciało przepływa magiczna moc.$B$BPo wewnętrznej stronie obrączki widnieje mały, ale wyraźny odcisk pieczęci Żelaznej Kuźni. Obok wygrawerowano trzy małe inicjały: „TdK”. Mogą to być inicjały poprzedniego właściciela albo może twórcy pierścienia. Zatrzymać pierścień... czy zwrócić go tej osobie? Trudny wybór...', 'Możesz zatrzymać pierścień albo odnaleźć osobę, do której należy odcisk i grawer po wewnętrznej stronie obrączki.', '', '', '', '', '', '', 0),
(2949, 'koKR', 'Powrót pierścienia', 'Po otwarciu pudełka, które wypluł Błyskomat 5200, znajdujesz lśniący pierścień! Gdy go zakładasz, czujesz, jak przez twoje ciało przepływa magiczna moc.$B$BPo wewnętrznej stronie obrączki widnieje mały, ale wyraźny odcisk pieczęci Orgrimmaru. Obok wygrawerowano litery, ale nawet po czyszczeniu czytelne są tylko pierwsze trzy: „NOG...”.$B$BMogą to być inicjały poprzedniego właściciela albo może twórcy pierścienia. Zatrzymać pierścień... czy odnaleźć „NOG”? Trudny wybór...', 'Możesz zatrzymać pierścień albo odnaleźć osobę, do której należy odcisk i grawer po wewnętrznej stronie obrączki.', '', '', '', '', '', '', 0),
(2951, 'koKR', 'Błyskomat 5200!', 'To ustrojstwo wyróżnia się pośród gnomów, które bronią się przed szaleństwem panującym za drzwiami. Na małej tabliczce na urządzeniu widnieje napis „Błyskomat 5200”, a pod nim tekst:$B$B„Brud i osad niszczą twoje błyskotki? Błyskomat 5200 przywróci im błyskotastyczny blask! Włóż przedmiot, który chcesz wyczyścić, i wrzuć do szczeliny trzy srebrne monety. Daj Błyskomatowi 5200 chwilę na pracę i voilà! Twoje kosztowności wyjdą czyste i lśniące!”', 'Włóż przedmiot pokryty brudem do Błyskomatu 5200 i pamiętaj, że do uruchomienia maszyny potrzebujesz trzech srebrnych monet.', '', 'Wróć do Błyskomatu 5200 w Srebrzystym Borze.', '', '', '', '', 0),
(2952, 'koKR', 'Błyskomat 5200!', '', '', '', '', '', '', '', '', 0),
(2953, 'koKR', 'Błyskomat znów w akcji', '', '', '', 'Wróć do Błyskomatu 5200 w Międzygórzu.', '', '', '', '', 0),
(2962, 'koKR', 'Jedyne lekarstwo to więcej zielonej poświaty', 'Twoja próbka nie tylko była za mała, ale też zanieczyszczona.$B$BPotrzebujemy więcej zielonej poświaty. Troggi są najwyraźniej za słabo napromieniowane, by zaspokoić nasze potrzeby. Musisz udać się do Gnomoregan i przynieść radioaktywny opad prosto ze źródła. Mówię o napromieniowanych szlamach, czaicielach i koszmarach. Uważaj jednak – taki opad trudno zatrzymać w naczyniu. Być może będziesz $gmusiał:musiała; kilka razy spróbować z fiolką, zanim uzyskasz odpowiednią próbkę.', 'Udaj się do Gnomoregan i przynieś silnie radioaktywny opad. Uważaj – opad jest niestabilny i dość szybko się rozpada.$B$BOzzie będzie też potrzebował twojej ciężkiej ołowianej fiolki na próbki, gdy wykonasz zadanie.$B', '', 'Wróć do Ozziego Pstrykowolta w Kharanos w Dun Morogh.', '', '', '', '', 0),
(2997, 'koKR', '', 'Witaj, $N. Wiem, że masz pełne ręce roboty z pomaganiem mieszkańcom Dun Morogh, ale kiedy znajdziesz czas, $gpowinieneś:powinnaś; wybrać się do Żelaznej Kuźni i porozmawiać z jedną z najbardziej szanowanych osób w naszym zakonie: Tizą Bojokuć. To do niej przychodzą młodsi paladyni, kiedy nadchodzi pora, by dowiedzieć się więcej o Światłości i o tym, czego się od nich oczekuje.$B$BZnajdziesz ją na piętrze Sali Tajemnic. Jeśli jeszcze tam nie $gbyłeś:byłaś;, to w Dzielnicy Mistycznej. Powodzenia, $N.', '', '', '', '', '', '', '', 0),
(3106, 'koKR', 'Prosta runa', 'Kiedy mi $gpomagałeś:pomagałaś;, dostałem tę runę, żebym ci ją przekazał. Przeczytaj ją, kiedy znajdziesz chwilę. Coś mi się widzi, że to od Thrana, nauczyciela wojowników. Rzuć na nią okiem i przy okazji odszukaj go w Kowadlinie.', 'Przeczytaj prostą runę i porozmawiaj z Thranem Khormanem w Dolinie Zimnej Grani.', '', '', '', '', '', '', 0),
(3107, 'koKR', 'Poświęcona runa', 'Kiedy mi $gpomagałeś:pomagałaś;, dostałem tę runę, żebym ci ją przekazał. Przeczytaj ją, kiedy znajdziesz chwilę. Coś mi się widzi, że to od Bromosa, nauczyciela paladynów. Rzuć na nią okiem i przy okazji odszukaj go w Kowadlinie.', 'Przeczytaj poświęconą runę i porozmawiaj z Bromosem Grummnerem w Dolinie Zimnej Grani.', '', '', '', '', '', '', 0),
(3108, 'koKR', 'Wytrawiona runa', 'Kiedy mi $gpomagałeś:pomagałaś;, dostałem tę runę, żebym ci ją przekazał. Przeczytaj ją, kiedy znajdziesz chwilę. Coś mi się widzi, że to od Thorgasa, nauczyciela łowców. Rzuć na nią okiem i przy okazji odszukaj go w Kowadlinie.', 'Przeczytaj wytrawioną runę i porozmawiaj z Thorgasem Grimsonem w Dolinie Zimnej Grani.', '', '', '', '', '', '', 0),
(3109, 'koKR', 'Zaszyfrowana runa', 'Kiedy mi $gpomagałeś:pomagałaś;, dostałem tę runę, żebym ci ją przekazał. Przeczytaj ją, kiedy znajdziesz chwilę. Coś mi się widzi, że to od Solma, nauczyciela łotrzyków. Rzuć na nią okiem i przy okazji odszukaj go w Kowadlinie.', 'Przeczytaj zaszyfrowaną runę i porozmawiaj z Solmem Hargrinem w Dolinie Zimnej Grani.', '', '', '', '', '', '', 0),
(3110, 'koKR', 'Uświęcona runa', 'Kiedy mi $gpomagałeś:pomagałaś;, dostałem tę runę, żebym ci ją przekazał. Przeczytaj ją, kiedy znajdziesz chwilę. Coś mi się widzi, że to od Branstocka, nauczyciela kapłanów. Rzuć na nią okiem i przy okazji odszukaj go w Kowadlinie.', 'Przeczytaj uświęconą runę i porozmawiaj z Branstockiem Khalderem w Kowadlinie.', '', '', '', '', '', '', 0),
(3112, 'koKR', 'Prosta notatka', 'Kiedy mi $gpomagałeś:pomagałaś;, dostałem tę notatkę, żebym ci ją przekazał. Przeczytaj ją, kiedy znajdziesz chwilę. Coś mi się widzi, że to od Thrana, nauczyciela wojowników. Rzuć na nią okiem i przy okazji odszukaj go w Kowadlinie.', 'Przeczytaj prostą notatkę i porozmawiaj z Thranem Khormanem w Dolinie Zimnej Grani.', '', '', '', '', '', '', 0),
(3113, 'koKR', 'Zaszyfrowana notatka', 'Kiedy mi $gpomagałeś:pomagałaś;, dostałem tę notatkę, żebym ci ją przekazał. Przeczytaj ją, kiedy znajdziesz chwilę. Coś mi się widzi, że to od Solma, nauczyciela łotrzyków. Rzuć na nią okiem i przy okazji odszukaj go w Kowadlinie.', 'Przeczytaj zaszyfrowaną notatkę i porozmawiaj z Solmem Hargrinem w Dolinie Zimnej Grani.', '', '', '', '', '', '', 0),
(3114, 'koKR', 'Notatka z glifami', 'Kiedy mi $gpomagałeś:pomagałaś;, dostałem tę notatkę, żebym ci ją przekazał. Przeczytaj ją, kiedy znajdziesz chwilę. Coś mi się widzi, że to od Marryka, nauczyciela magów. Rzuć na nią okiem i przy okazji odszukaj go w Kowadlinie.', 'Przeczytaj notatkę z glifami i porozmawiaj z Marrykiem Nurribitem w Kowadlinie nad Doliną Zimnej Grani.', '', '', '', '', '', '', 0),
(3115, 'koKR', 'Skażona notatka', 'Kiedy mi $gpomagałeś:pomagałaś;, dostałem tę notatkę, żebym ci ją przekazał. Przeczytaj ją, kiedy znajdziesz chwilę. Coś mi się widzi, że to od Alamara, nauczyciela czarnoksiężników. Rzuć na nią okiem i przy okazji odszukaj go w Kowadlinie.$B$BI uważaj na siebie, $N, tacy jak ty nie cieszą się w tych stronach zbytnim zaufaniem.', 'Przeczytaj skażoną notatkę i porozmawiaj z Alamarem Grimmem w Kowadlinie nad Doliną Zimnej Grani.', '', '', '', '', '', '', 0),
(3361, 'koKR', 'Kłopot uchodźcy', 'Wypędziliśmy troggi z Gnomoregan, ale potem wszystko poszło strasznie źle! Teraz nasz dom jest całkowicie napromieniowany, a my, gnomy, rozproszyliśmy się po całym Dun Morogh.$B$BUciekając w pośpiechu przed promieniowaniem, straciłem cały dobytek i narzędzia. Dorwały je trolle. Ukradły mi kufer, pudełko i wiadro śrub! Zabrały je do swoich obozów na południowy zachód od Kowadlina.$B$BŻaden ze mnie poszukiwacz przygód – czy $gmógłbyś:mogłabyś; odnaleźć moje rzeczy i przynieść mi je tutaj?', 'Przynieś pudełko Felixa, kufer Felixa i wiadro śrub Felixa Felixowi Whindleboltowi w Kowadlinie.', '', 'Wróć do Felixa Whindlebolta na Przełęczy Zimnej Grani w Dun Morogh.', '', '', '', '', 0),
(3364, 'koKR', 'Dostawa porannego naparu', 'Ech! Już dawno miałem zanieść ten pyszny, parzący poranny napar Durnanowi Futrokrojowi do Kowadlina, ale najpierw musiałem dostarczyć jeden Grelinowi. Nigdy nie zdążę do Kowadlina, zanim napar wystygnie!$B$BWyglądasz na kogoś szybkiego. Może tobie się uda. Ten kubek utrzyma ciepło jeszcze tylko przez kilka minut, a Durnan nie zamawiał „chłodnego” naparu, więc ruszaj. Kowadlin leży na północnym wschodzie, to osada wykuta w zboczu góry.$B$BDzięki, $N, i nie zapomnij mi oddać kufla!', 'Zanieś parzący poranny napar Durnanowi Futrokrojowi do Kowadlina, zanim wystygnie!', '', '', '', '', '', '', 0),
(3365, 'koKR', 'Odnieś kufel', 'Tego mi było trzeba! Nie ma to jak gorący – co ja mówię, PARZĄCY – poranny napar w mroźny zimowy dzień, żeby rozgrzać duszę do samego dna.$B$BProszę, $N – bądź tak $gdobry:dobra; i odnieś za mnie ten pusty kufel Noriemu, dobrze?', 'Oddaj kufel Noriego Noriemu Dumnozaspowi w Dolinie Zimnej Grani.', '', '', '', '', '', '', 0),
(4126, 'koKR', 'Hurley Czarnodech', 'Krasnoludy z klanu Czarnorytych, prowadzone przez łotra Hurleya Czarnodecha, ukradły jeden z najlepszych przepisów Gromowarów – na lager Gromowarów. Nikczemnicy! Nie zasługują na tak zacny trunek!$B$B$N, mam dla ciebie trudne zadanie. Udaj się do Otchłani Czarnej Góry na Płonących Stepach, zniszcz wszystkie beczułki lagera Gromowarów, jakie znajdziesz, i odzyskaj nasz przepis na lager Gromowarów!$B$BProszę, odzyskaj ten przepis, nawet gdybyś $gmiał:miała; wywrócić Otchłań Czarnej Góry do góry nogami!', 'Przynieś zaginiony przepis Gromowarów Ragnarowi Gromowarowi w Kharanos.', '', 'Wróć do Ragnara Gromowara w Kharanos w Dun Morogh.', '', '', '', '', 0),
(4128, 'koKR', 'Ragnar Gromowar', 'Hej, $n. Słyszałam, że Ragnar Gromowar aż kipi ze złości, bo ktoś ukradł mu piwo. Szuka dzielnych śmiałków i dobrze płaci.$B$BJeśli cię to interesuje, porozmawiaj z Ragnarem. Znajdziesz go w Gorzelni Gromowarów w Kharanos, w Dun Morogh.', 'Porozmawiaj z Ragnarem Gromowarem.', '', '', '', '', '', '', 0),
(4601, 'koKR', 'Błyskomat 5200!', 'To ustrojstwo wyróżnia się pośród gnomów, które bronią się przed szaleństwem panującym za drzwiami. Na małej tabliczce na urządzeniu widnieje napis „Błyskomat 5200”, a pod nim tekst:$B$B„Brud i osad niszczą twoje błyskotki? Błyskomat 5200 przywróci im błyskotastyczny blask! Włóż przedmiot, który chcesz wyczyścić, i wrzuć do szczeliny trzy srebrne monety. Daj Błyskomatowi 5200 chwilę na pracę i voilà! Twoje kosztowności wyjdą czyste i lśniące!”', 'Włóż przedmiot pokryty brudem do Błyskomatu 5200 i pamiętaj, że do uruchomienia maszyny potrzebujesz trzech srebrnych monet.', '', 'Wróć do Błyskomatu 5200 w Międzygórzu.', '', '', '', '', 0),
(4602, 'koKR', 'Błyskomat 5200!', 'To ustrojstwo wyróżnia się pośród gnomów, które bronią się przed szaleństwem panującym za drzwiami. Na małej tabliczce na urządzeniu widnieje napis „Błyskomat 5200”, a pod nim tekst:$B$B„Brud i osad niszczą twoje błyskotki? Błyskomat 5200 przywróci im błyskotastyczny blask! Włóż przedmiot, który chcesz wyczyścić, i wrzuć do szczeliny trzy srebrne monety. Daj Błyskomatowi 5200 chwilę na pracę i voilà! Twoje kosztowności wyjdą czyste i lśniące!”', 'Włóż przedmiot pokryty brudem do Błyskomatu 5200 i pamiętaj, że do uruchomienia maszyny potrzebujesz trzech srebrnych monet.', '', 'Wróć do Błyskomatu 5200 w Srebrzystym Borze.', '', '', '', '', 0),
