(5541, 'koKR', 'Amunicja dla Hukostrzała', 'Hegnar Hukostrzał sprzedaje broń palną przy drodze do Kowadlina. Strzelcy i obsługa moździerzy dużo ćwiczą w pobliżu jego sklepu, więc ciągle potrzebuje świeżej amunicji.$B$BAle... ostatnia skrzynia amunicji, którą mu wysłałem, zaginęła po drodze. Mój posłaniec mówi, że rozbił obóz koło Siwej Nory, kiedy przegoniły go wendigo... a ten głupiec zostawił tam amunicję Hukostrzała!$B$B$N, możesz odzyskać tę amunicję i zanieść ją Hukostrzałowi? Czeka na nią i na pewno kończą mu się zapasy.', 'Przynieś amunicję Hukostrzała Hegnarowi Hukostrzałowi w Dun Morogh.', '', 'Wróć do Hegnara Hukostrzała w Dun Morogh.', '', '', '', '', 0),
(5625, 'koKR', '', 'Zwykle mniej więcej o tej porze ktoś o twojej mocy przechodzi próbę, która ma pokazać, czy jest godzien nosić szaty świadczące o jego miejscu w Kościele. Ale szczerze mówiąc, mam pilniejsze sprawy na głowie. Przyszedł tu właśnie jeden z mieszkańców Kharanos i powiedział mi o rannym górskim strażniku tuż za miastem, na południu – nazywa się Dolf.$B$BUlecz Dolfa i obdarz go Wytrwałością, a uznam, że już się $gwykazałeś:wykazałaś;. Co ty na to?', 'Znajdź górskiego strażnika Dolfa i ulecz jego rany Pomniejszym leczeniem (ranga 2). Następnie obdarz go Słowem mocy: Wytrwałość i wróć do Maxana Anvola w Kharanos.', '', 'Wróć do Maxana Anvola na Migoczącej Grani w Dun Morogh.', 'Ulecz i wzmocnij górskiego strażnika Dolfa', '', '', '', 0),
(5626, 'koKR', '', 'Hej! $N! Masz chwilkę?!$B$BPodążasz za Światłością już na tyle długo, że pora, byś $gudał:udała; się do Maxana Anvola w Kharanos. Nauczy cię więcej o ścieżce, którą kroczysz, a jeśli okażesz się $ggodny:godna;, da ci pierwsze szaty, oznakę twojej pozycji $gkapłana:kapłanki;.$B$BA teraz ruszaj! Gdy tylko skończysz tutaj, przejdź przez tunel – będzie na ciebie czekał.', 'Porozmawiaj z Maxanem Anvolem w Dun Morogh.', '', '', '', '', '', '', 0),
(5841, 'koKR', '', 'Witaj w World of Warcraft!$B$BW podziękowaniu za zakup Edycji Kolekcjonerskiej World of Warcraft oddaj ten bon podarunkowy Yoriemu Pękohełmowi w Kharanos. W zamian otrzymasz prezent: małego towarzysza, który będzie ci towarzyszył w poszukiwaniu przygód i chwały.$B$BJeszcze raz dziękujemy i życzymy udanego pobytu w świecie World of Warcraft!', 'Zanieś bon podarunkowy z Kharanos Yoriemu Pękohełmowi w Kharanos.', '', '', '', '', '', '', 0),
(6064, 'koKR', 'Oswajanie bestii', 'Witaj, $Gchłopcze:dziewczyno;! Czyli chcesz się dowiedzieć, jak zdobyć własnego zwierzaka?$B$BNo to zaczynajmy. Na polowaniu nie ma nic ważniejszego niż sprzęt, ale o moim nowym garłaczu odłamkowym pogadamy innym razem. Na razie skupmy się na czymś, co na pewno cię ciekawi: na zwierzaku!$B$BNajlepiej nauczysz się, jeśli wypróbujesz kilka stworzeń jako towarzyszy i zobaczysz, co ci pasuje. Znajdź więc dużego dzika skalnego i oswój go za pomocą różdżki oswajania.', 'Użyj różdżki oswajania, żeby oswoić dużego dzika skalnego. Poćwicz swoje umiejętności, a potem oddaj różdżkę oswajania Grifowi Sercu Dziczy w Kharanos.', 'Oswój dużego dzika skalnego', 'Wróć do Grifa Serce Dziczy w Kharanos w Dun Morogh.', '', '', '', '', 0),
(6084, 'koKR', 'Oswajanie bestii', 'Te dziki skalne są dość toporne. Może wolisz coś z odrobiną finezji? No dobrze, mam coś w sam raz. Na południowy wschód stąd znajdziesz duże białe koty zwane lampartami śnieżnymi. Jak w pięknie rzeźbionej strzelbie, za ich urodą kryje się groźny wojownik, zdolny zadać potężne obrażenia. Przekonasz się, że są dużo zwinniejsze i szybsze niż dzik, $gktórego oswoiłeś:którego oswoiłaś;.$B$BWeź tę różdżkę oswajania i sprawdź, jak ci się spodoba lampart śnieżny.', 'Użyj różdżki oswajania, żeby oswoić lamparta śnieżnego. Poćwicz swoje umiejętności, a potem wróć do Grifa Serce Dziczy w Kharanos.', 'Oswój lamparta śnieżnego', 'Wróć do Grifa Serce Dziczy w Kharanos w Dun Morogh.', '', '', '', '', 0),
(6085, 'koKR', 'Oswajanie bestii', 'Może wolisz stworzenie, które ma przede wszystkim czystą siłę? Lodopazury niedźwiedź to świetny towarzysz dla takiego żółtodzioba jak ty, a znajdziesz go na wschód od Kharanos. Oto różdżka oswajania. Wypróbuj to zwierzę i zobacz, czy ci odpowiada!$B$BKiedy wrócisz, przekażę ci umiejętności potrzebne do oswojenia wybranego zwierzęcia. Takie stworzenie stawi czoła tym samym wyzwaniom co ty i będzie zdobywać doświadczenie razem z tobą. Pokażę ci też, jak je przywoływać i odprawiać, kiedy zechcesz.$B', 'Użyj różdżki oswajania, żeby oswoić lodopazurego niedźwiedzia. Poćwicz swoje umiejętności, a potem oddaj różdżkę oswajania Grifowi Sercu Dziczy w Kharanos.', 'Oswój lodopazurego niedźwiedzia', 'Wróć do Grifa Serce Dziczy w Kharanos w Dun Morogh.', '', '', '', '', 0),
(6086, 'koKR', 'Szkolenie bestii', '$N, potrafisz już oswoić zwierzaka, ale musisz jeszcze zdobyć umiejętności, żeby go szkolić.$B$BUdaj się do Żelaznej Kuźni i znajdź Salę Oręża. Tam porozmawiaj z jedną z naszych najbardziej szanowanych treserek, Belią Gromogranit. Ona da ci moc szkolenia twojego nowego zwierzaka, więc ruszaj, $gchłopcze:dziewczyno;!$B$BBelia jest przyjazna, nie powinno być kłopotu z tym, żeby cię zaakceptowała. Powodzenia, $N.$B', 'Porozmawiaj z Belią Gromogranit w Żelaznej Kuźni.', '', '', '', '', '', '', 0),
(7673, 'koKR', 'Wymiana mroźnego barana', '', '', '', 'Wróć do Verona Amberstilla w Dun Morogh.', '', '', '', '', 0),
(7674, 'koKR', 'Wymiana czarnego barana', '', '', '', 'Wróć do Verona Amberstilla w Dun Morogh.', '', '', '', '', 0),
(7675, 'koKR', 'Zamiennik lodowoniebieskiego mechabiegusa', '', '', '', 'Wróć do Milli Piórogwizd w Dun Morogh.', '', '', '', '', 0),
(7676, 'koKR', 'Zamiennik białego mechabiegusa', '', '', '', 'Wróć do Milli Piórogwizd w Dun Morogh.', '', '', '', '', 0),
(14083, 'koKR', 'Naucz się jeździć w Dun Morogh', 'Tę ulotkę reklamującą naukę jazdy i sprzedaż wierzchowców przysłał Ultham Żelaznoróg.$B$BUlthama można znaleźć na Ranczu Amberstill w Dun Morogh, przy drodze prowadzącej na wschód od Żelaznej Kuźni.', 'Zanieś ulotkę Ulthamowi Żelaznorogowi na Ranczo Amberstill w Dun Morogh.', '', 'Wróć do Ulthama Żelaznoroga na Ranczu Amberstill w Dun Morogh.', '', '', '', '', 0),
(14084, 'koKR', 'Naucz się jeździć w Dun Morogh', 'Tę ulotkę reklamującą naukę jazdy i sprzedaż wierzchowców przysłał Binjy Piórogwizd.$B$BBinjy\'ego można znaleźć w Składzie Steelgrilla, tuż na północny wschód od Kharanos w Dun Morogh.', 'Zanieś ulotkę Binjy\'emu Piórogwizdowi do Składu Steelgrilla w Dun Morogh.', '', 'Wróć do Binjy\'ego Piórogwizda w Składzie Steelgrilla w Dun Morogh.', '', '', '', '', 0),
(25199, 'koKR', 'Podstawowe rozkazy', 'Hej! Wyglądasz na kogoś, kto mógłby nam pomóc!$B$BJeśli chcesz wesprzeć naszą sprawę, musisz przejść szkolenie. Gnomie szkolenie jest brutalne i wymagające, więc mam nadzieję, że jesteś $ggotów:gotowa;.$B$BIdź do instruktora musztry Parokorba, on przeprowadzi cię przez wszystko, co musisz wiedzieć. Wykonuj jego rozkazy, kiedy je wydaje, bo inaczej nigdy nie dasz rady.$B$BAle ostrzegam, tam jest ciężko. Wróć do mnie, jeśli przetrwasz.', 'Wykonuj polecenia instruktora musztry Parokorba, a potem zgłoś się do kapitana Treada Iskrodyszy.', '', 'Zgłoś się do kapitana Treada Iskrodyszy.', 'Zasalutuj instruktorowi musztry', 'Zarycz z instruktorem musztry', 'Wiwatuj z instruktorem musztry', 'Zatańcz z instruktorem musztry', 0),
(25212, 'koKR', 'Horyzont wentylacji', 'Myśleliśmy, że wystarczy przeczekać, aż promieniowanie wokół Gnomoregan opadnie, ale wcale nie wygląda na to, żeby było lepiej.$B$BJeśli chcemy odbić nasze miasto, musimy się upewnić, że nasze oddziały mogą bezpiecznie do niego wejść.$B$BWeź te radiogeigatrony, wskakuj do „Gromobłysku” i zrzuć je na szyby wentylacyjne wokół Gnomoregan. Będą przesyłać odczyty promieniowania prosto do mnie.', 'Użyj latającej maszyny pilota Muzzlesprocka, żeby zrzucić radiogeigatrony na otwory wentylacyjne wokół Gnomoregan.', '', 'Porozmawiaj z pilotem Muzzlesprockiem.', 'Rozstaw radiogeigatron przy otworach wentylacyjnych Gnomoregan', '', '', '', 0),
(25229, 'koKR', 'Gnomy honoru', 'Nasi inżynierowie przygotowują machiny bojowe do szturmu na Gnomoregan, ale skończyli nam się piloci!$B$BOpracowaliśmy urządzenie zwane Motywatronem, które odcina wszystko, co rozprasza, i dodaje gnomowi odwagi, żeby się zaciągnął.$B$BKiedy zmotywujesz kilku gnomich obywateli, zaprowadź ich do kapitana Treada Iskrodyszy przy Składzie Steelgrilla, tuż na południe od Żelaznej Kuźni.$B$BA, i uważaj. Urządzenie jest wciąż trochę eksperymentalne.\n', 'Zwerbuj gnomich obywateli w Majsterkowie za pomocą Motywatronu i zaprowadź ich do kapitana Treada Iskrodyszy przy Składzie Steelgrilla.', '', 'Porozmawiaj z kapitanem Treadem Iskrodyszą przed Składem Steelgrilla.', 'Zmotywowane gnomy', 'Zmotywowane gnomy doprowadzone do kapitana Iskrodyszy', '', '', 0),
(25283, 'koKR', 'Szlifowanie przemowy', 'Wielki Majster Mekanownik poprosił mnie o napisanie przemowy, którą mógłby wygłosić przed rozpoczęciem bitwy, ale sam nie potrafię ocenić, która wersja jest dobra, a które po prostu śmierdzą.$b$b$gMógłbyś:Mogłabyś; wypróbować kilka z nich na tutejszych gnomach? To urządzenie wyświetla obraz Mekanownika wygłaszającego po kilka zdań z każdej mojej wersji.$b$bDaj mi znać, która działa, dobrze?', 'Użyj gnomiego urządzenia odtwarzającego przed Ozziem Pstrykowoltem na północ od Kharanos, Milli Piórogwizd w Składzie Steelgrilla i Togiem Rdzawotrybem przed karczmą w Kharanos. Kiedy wszystkie przemowy zostaną odtworzone, wróć do Toby\'ego Zeigeara.', '', 'Wróć do Toby\'ego Zeigeara w Składzie Steelgrilla.', 'Odtwórz przemowę przed Ozziem Pstrykowoltem', 'Odtwórz przemowę przed Milli Piórogwizd', 'Odtwórz przemowę przed Togiem Rdzawotrybem', '', 0),
(25285, 'koKR', 'Wsiadka i wysiadka', 'Musimy przygotować te nowe mechaczołgi do szturmu. Jesteś $ggotów:gotowa; pomóc w testowaniu tych maleństw?! Jasne, że tak!$b$bNajpierw musimy się upewnić, że jak już wsiądziesz, to zdołasz też wysiąść. Jeśli w bitwie uznasz, że twój czołg zaraz wybuchnie, wyskakuj! Widziałem wielu gnomów, którzy siedzieli w środku do gorzkiego końca... czołg wylatywał w powietrze, a oni razem z nim.$B$BNo więc wyposażyłem ten czołg w fotel katapultowy. Wypróbujesz go dla mnie, co?', 'Przetestuj system katapultowania w wyrzutowym mechaczołgu.', '', 'Daj znać kapitanowi Treadowi Iskrodyszy, że $gkatapultowałeś:katapultowałaś; się bezpiecznie.', 'System katapultowania przetestowany', '', '', '', 0),
(25286, 'koKR', 'Słowa do przekazania', 'No i proszę. Oto przemowa, $N!$b$bMa wszystko, czego trzeba, żeby porywająco rozpocząć bitwę: jest natchniona, wyszukana w słowach i przemawia prosto do gnomów. Nigdy jeszcze nie napisano lepszej przemowy!$b$bZanieś ją kapitanowi Treadowi Iskrodyszy i załatw sobie transport do Wielkiego Majstra Mekanownika!', 'Przekaż przemowę kapitanowi Treadowi Iskrodyszy w Składzie Steelgrilla.', '', 'Porozmawiaj z kapitanem Treadem Iskrodyszą w Składzie Steelgrilla.', '', '', '', '', 0),
(25287, 'koKR', 'Słowa do przekazania', 'Dobra, żołnierzu. Czas pokazać, ile jesteś $gwart:warta;!$B$BWeź przemowę i wsiadaj na pokład latającej maszyny „Gromobłysk”. To najszybszy statek, jakim dotrzesz do Wielkiego Majstra Mekanownika, a on czeka już tylko na tę przemowę, żeby rozpocząć Operację: Gnomoregan.$B$BRuszaj! Już!', 'Poleć „Gromobłyskiem” ze Składu Steelgrilla do Wielkiego Majstra Mekanownika i przekaż mu przemowę Toby\'ego.', '', 'Przekaż przemowę Mekanownika Wielkiemu Majstrowi Mekanownikowi.', '', '', '', '', 0),
(25289, 'koKR', 'Krok naprzód...', 'Skoro system katapultowania działa, możemy chyba przetestować ruch. Ten czołg ma wyjątkową funkcję: automatyczne manewry wymijające!$b$bSprawdź serwomechanizmy lewej nogi, prawej nogi i system automatycznego wymijającego manewru.$b$bTo proste sprawy, nie powinno ci zająć dużo czasu.', 'Sprawdź zwrotność drepczącego mechaczołgu.', '', 'Przekaż kapitanowi Treadowi Iskrodyszy wyniki testów.', 'Serwomechanizmy lewej nogi przetestowane', 'Serwomechanizmy prawej nogi przetestowane', 'System wymijającego manewru przetestowany', '', 0),
(25295, 'koKR', 'Wciśnij spust', 'Systemy bezpieczeństwa – działają! Funkcje motoryczne – funkcjonują! Teraz musimy tylko sprawdzić, czy działka strzelają.$b$bTo nie powinno być trudne, $n. Mechaczołg na wzgórzu za nami załadowano niegroźnym śrutem. Oddaj kilka serii do pobliskich celów i zamelduj mi o wynikach.', 'Przetestuj systemy uzbrojenia strzelającego mechaczołgu na pobliskich celach.', '', 'Przekaż kapitanowi Treadowi Iskrodyszy wyniki testów.', 'System uzbrojenia przetestowany', '', '', '', 0),
(25393, 'koKR', 'Operacja: Gnomoregan', 'Za chwilę rozpocznie się wielofazowy szturm na Gnomoregan, a mechinżynier Termowtyk i jego ludzie staną przed obliczem sprawiedliwości! Zbyt długo Termowtyk gnił w głębinach naszego domu, bronionego przez zepsutą i napromieniowaną armię.$B$BSzturm zacznie się lada moment! Bądź $ggotów:gotowa;, rekrucie, ta walka nie będzie dla strachliwych.', 'Pomóż królowi Mekanownikowi w szturmie na Gnomoregan.', '', 'Porozmawiaj z królem Mekanownikiem w Majsterkowie.', 'Odbij powierzchnię Gnomoregan', '', '', '', 0),
(25500, 'koKR', 'Słowa do przekazania', 'No i proszę. Oto przemowa, $N!$b$bMa wszystko, czego trzeba, żeby porywająco rozpocząć bitwę: jest natchniona, wyszukana w słowach i przemawia prosto do gnomów. Nigdy jeszcze nie napisano lepszej przemowy!$b$bZanieś ją kapitanowi Treadowi Iskrodyszy i sprawdź, czy nie potrzebuje od ciebie czegoś jeszcze.', 'Przekaż przemowę kapitanowi Treadowi Iskrodyszy w Składzie Steelgrilla.', '', 'Przekaż przemowę Wielkiemu Majstrowi Mekanownikowi.', '', '', '', '', 0);
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES
(170, 'koKR', 'Jeśli nasze kłopoty tutaj świadczą o tym, co dzieje się w innych częściach naszych ziem, to na brodę Magniego, czekają nas ciężkie czasy! Mogę tylko mieć nadzieję, że król i Senat podejmują kroki przeciwko zagrożeniu ze strony troggów.', 0),
(179, 'koKR', 'Ach! Wspaniale. To wilcze mięso świetnie się nada. Och, nie martw się, $N, nie zapomniałem o swojej części umowy. Proszę, któraś z tych par powinna na ciebie pasować.', 0),
(182, 'koKR', 'Argh! Niech Światłość pokarze te trolle!$B$B<Bierze kilka głębokich oddechów i wydaje się uspokajać... odrobinę.>$B$BBanda tych stworów przyszła w nocy i ukradła mój dziennik! Wiedziałem, że nie należy ufać temu nicponiowi, mojemu ucz...', 0),
(183, 'koKR', 'Wspaniale! Teraz mogę wrócić do moich... niespiesznych... polowań. Dziękuję ci, $N.', 0),
(218, 'koKR', 'Wspaniale, $N! Wielkie dzięki za odzyskanie mojego notatnika. Cóż, wygląda na to, że sytuacja z trollami tu, w Dolinie Zimnej Grani, jest pod kontrolą i nie ma powodów do wielkich obaw.$b$bKiedy dopracuję swój raport, będę potrzebował kogoś, kto zaniesie go mojemu bratu, Senirowi.', 0),
(233, 'koKR', 'Dziękuję, od dawna czekam na te listy...$b$bNiestety nie wszystkie są do mnie. Ten jest zaadresowany do Grelina Białobrodego. To niedaleko, jeśli zechcesz mu go dostarczyć.', 0),
(234, 'koKR', 'Ach, doskonale. Dawno nie dostałem wieści z Żelaznej Kuźni.', 0),
(282, 'koKR', 'Hm, cóż, skoro Białobrody wysyła cię do Dun Morogh w ważnej sprawie, trudno mi cię zatrzymywać, prawda?$b$bPozwól przynajmniej, że dam ci kilka rad i wskażę drogę.', 0),
(287, 'koKR', 'Ach, $N! Nie sądziłem, że będziesz $gmiał:miała; kłopot ze znalezieniem tego miejsca, moje wskazówki są przecież doskonałe...$b$bPozwól, że tylko dokończę raport.$b$b<Wyjmuje kartkę i przez chwilę coś na niej gryzmoli.>$b$bGotowe! No, ha, ha, to ci dopiero zabawne... Chyba nie odmówisz mi, $N, jeszcze jednej, ostatniej przysługi?', 0),
(291, 'koKR', '<Pospiesznie przegląda raport.>$b$bZ upoważnienia KRÓLA!? Czy Magni do reszty postradał zmysły? A ten przeklęty Białobrody... Wziął sprawy w swoje ręce, co? Senat nie będzie zadowolony, gdy o tym usłyszy, ani trochę.$b$bCo, jeszcze tu jesteś? Idź, zanim zawołam straże!', 0),
(308, 'koKR', 'Dla mnie? Jesteś $gprawdziwym bohaterem:prawdziwą bohaterką;, $N!', 0),
(310, 'koKR', 'Szybko stawiasz beczkę Parzącego Jęczmiennego Browaru od Marleth wśród beczek Gromowarów.', 0),
(311, 'koKR', 'Nieźle, $N! Trudno było przemknąć się obok ich strażnika?$B$BMniejsza z tym – wielkie dzięki, a jeśli kiedyś zachce ci się stouta z kopem, nie zapomnij o Jęczmieniowarach!', 0),
(312, 'koKR', 'Dobra z ciebie dusza, $N! Dzięki twojej odwadze nie umrę z głodu, kiedy przyjdą zimowe zawieruchy.', 0),
(313, 'koKR', 'Ach tak, te grzywy świetnie się nadadzą! Masz w sobie sporo hartu – niejeden $c mógłby ci go pozazdrościć. Założę się, że czekają cię wielkie czyny.', 0),
(314, 'koKR', 'Świetna robota! Veron bardzo się ucieszy, kiedy usłyszy dobrą nowinę. Zabicie Vagasha to nie lada wyczyn. Wyobrażam sobie, że pewnego dnia będziesz walczyć u boku żołnierzy króla Magniego na froncie Przymierza.', 0),
(315, 'koKR', 'Świetnie! Nie mogę się doczekać, aż dodam je do moich przepisów. Jest zwłaszcza jeden, w którym chyba sprawdzą się znakomicie...', 0),
(317, 'koKR', 'Na brodę Magniego, ależ się $gnapolowałeś:napolowałaś;! Dziękuję, $N.', 0),
(318, 'koKR', 'Bellowfiz potrzebuje mojego „Wiecznego blasku”? Hm... niech będzie.', 0),
(319, 'koKR', 'Dziękuję, $N. Miło będzie zajmować się rzemiosłem, nie słysząc tylu warknięć i chrząknięć pod wioską.', 0),
(320, 'koKR', 'Tak, to się świetnie nada. Chyba od razu otworzę butelkę i skosztuję...', 0),
(384, 'koKR', 'Słód uwarzony, dziki ubite,$BLecz nim cokolwiek zostanie dopite,$BStoczymy bój – kto pierwszy, szczęśliwy,$BBo żeberka z dzika w piwie to przysmak prawdziwy!', 0),
(400, 'koKR', 'Masz moje narzędzia? Dobra robota, $gchłopcze:dziewczyno;, dobra robota! Godzinę temu złamałem ostatnią kłową grzechotkę, a potrzebuję jej, żeby dokończyć naprawę machiny oblężniczej pilota Kamiennotryba. Dobrze $gzrobiłeś:zrobiłaś;, że $gprzytaszczyłeś:przytaszczyłaś; tu te narzędzia, $N.$b$bProszę, weź te monety za pomoc.', 0),
(403, 'koKR', 'Tej beczki piwa pilnuje Jarven Gromowar. Dopóki jest w piwnicy, żadnej beczki nie da się ruszyć.', 0),
(412, 'koKR', 'Te żyromechaniczne zębatki i trybiki restabilizacyjne w pełni odpowiadają schematom urządzenia rekombobulacyjnego, które opracował Ozzie. Gdy tylko dodam trochę hydrosmaru do tłoków spalania wewnętrznego, wyreguluję korbogrzechotkę i zwiększę lepkość żelu elektrogumowego, gnomia rasa będzie jak nowa.', 0),
(413, 'koKR', '<Górski strażnik Jęczmieniowar kosztuje połyskliwego stouta...>$B$BOch. Ho, ho! Po tym trunku aż oczy błyszczą. Czuję się, jakbym widział w ciemności!', 0),
(414, 'koKR', 'No, dajże spróbować...$b$bNa brodę Magniego! Od tego trunku aż w głowie się kręci! I członki robią się lżejsze.$b$bCzuję się, jakbym mógł latać!', 0),
(415, 'koKR', '$N! Pamiętasz połyskliwe ziele, które mi $gprzyniosłeś:przyniosłaś;? Użyłem go w kilku przepisach, nad którymi pracuję, i jeden z nich wyszedł znakomicie!$b$bMasz, spróbuj i powiedz, co o tym myślisz...', 0),
(417, 'koKR', 'To ponure wieści, bo Hildelve był moim dobrym przyjacielem. Żałuję, że nie było mnie z tobą, kiedy $gznalazłeś:znalazłaś; tę bestię, Parchopazura!$b$bDziękuję, $N. Piloci Brygady Oblężniczej Żelaznej Kuźni zapamiętają twój czyn.', 0),
(419, 'koKR', 'Oto zwłoki krasnoluda – poszarpane, zamarznięte i ogryzione do czysta przez górskich padlinożerców. W dłoni ściskają księgę z niechlujnie nabazgranymi notatkami Moriego Hildelve. Na ciele wciąż jest, w doskonałym stanie, kamizelka brygadiera.$b$bTo w tym ponurym miejscu pilot machiny oblężniczej musiał dokonać żywota.', 0),
(420, 'koKR', 'Co to? Ach, raport mojego brata. Hmm...$b$bMówiłem mu, żeby oszczędnie szafował imieniem króla, ale nie posłuchał. Pewnie nic złego się nie stanie, choć w Senacie na pewno zjeży to kilka bród. Nie żeby niektóre brody nie wymagały zjeżenia! Ha!$b$bTak czy inaczej, chyba powinienem teraz wysłać do Żelaznej Kuźni i swój raport, ale przyznaję, że trochę z nim zalegam. Cholerne zimno.$b$bJeśli zechcesz, później znajdę dla ciebie jakąś robotę.', 0),
(432, 'koKR', 'No, od razu mi trochę lepiej...$b$bAle nie spocznę, dopóki wszystkie nie zginą! Wszystkie co do jednego!', 0),
(433, 'koKR', 'To dopiero początek. Miejmy nadzieję, że zdołamy to wykorzystać i wprowadzić tam górskich strażników, by zabezpieczyli teren. Wtedy zaczniemy odbudowywać infrastrukturę i przywrócimy górników do pracy.$b$bDziękuję za pomoc, $N.', 0),
(466, 'koKR', 'Masz rudę! Dobra robota, $N! Zaraz znajdę kogoś, kto się tym zajmie. Miejmy nadzieję, że nie wysadzi się w powietrze!', 0),
(467, 'koKR', 'Witaj, $N. Przychodzisz w sprawie mojego zadania, co? Dobrze widzieć kogoś tak młodego, w kim krew aż się burzy na myśl o przygodzie!', 0),
(1679, 'koKR', 'Ach, $N. Słyszałem, jak wojownicy z Dun Morogh przerzucają się twoim imieniem. Mam nadzieję, że nie $gspędziłeś:spędziłaś; całego czasu w browarach!', 0),
(1783, 'koKR', 'Nie wiem, jak ci dziękować, $gbracie:siostro;.$B$BSkoro masz przy sobie Symbol Życia, mogę tylko przypuszczać, że Tiza i Muiredon przysłali cię tu na pomoc.$B$BTo prawda, poległem z rąk Czarnorytych, próbując zdobyć jedno z ich pism: zdołałem wytrzymać na tyle długo, by Muiredon mógł uciec, ale Światłość niemal całkiem mnie już objęła, kiedy się $gzjawiłeś:zjawiłaś;. To, że starczyło ci mocy, by użyć Symbolu, dobrze wróży twojej przyszłości, ale o tym porozmawiamy później.', 0),
(1784, 'koKR', 'Ha, ha! Udało ci się! $GUratowałeś:Uratowałaś; Narma i $gznalazłeś:znalazłaś; dowód, który moja żona musi przedstawić radzie. Jesteś błogosławieństwem Światłości, jakiego jeszcze nie widziałem... nie licząc mojej żony, ma się rozumieć.$B$BJeszcze raz dziękuję, $N.', 0),
(1879, 'koKR', 'Och, widzę, że masz talent, o tak! Ale żeby być dobrym magiem, potrzeba czegoś więcej niż talentu. A kto nie jest dobrym magiem, ten jest złym magiem. A źli magowie to część problemu, o tak!$b$bOjej, za daleko wybiegam. Zacznijmy od początku!', 0),
(2160, 'koKR', 'Ach, nareszcie zapasy od Handsa! Zaczynałem się już martwić – odkąd troggi opanowały przełęcz, z Kowadlina docierają do nas tylko strzępy wieści.$b$bDzięki, że mi to $gprzyniosłeś:przyniosłaś;, $N. I proszę, rozgość się. Musisz być $gzmęczony:zmęczona; po podróży.', 0),
(2218, 'koKR', 'Więc uważasz się za $gprawdziwego łajdaka:prawdziwą łajdaczkę;? Za kogoś, komu pisane jest znaleźć się wśród garstki wybrańców Czarnobrodego – wśród oficerów Ukrytego Kręgu?$B$BTylko nicpoń, co do niczego się nie nadaje, mógłby mieć o sobie tak wysokie mniemanie.$B$BI właśnie takich szukamy! Witaj na pokładzie, $N!', 0),
(2238, 'koKR', 'Ciii! Ciszej, zakuty łbie. Usłyszą nas.', 0),
(2239, 'koKR', 'Okrężną drogą? Na moją brodę!$B$BDobra robota, $N. Weź ten sztylet i zmykaj. Krąg znowu cię wezwie, kiedy krok trzeci będzie gotów do wprowadzenia w życie.$B$BCo to jest krok trzeci? Następuje zaraz po kroku drugim – czyli po tym, jak kopnę cię w zadek.$B$B$GZainteresowany:Zainteresowana;?', 0),
(2299, 'koKR', 'Ścisz głos, $N, strażnicy mogą cię usłyszeć.', 0),
(2841, 'koKR', 'Wiedziałem, że ci się uda, $N! Za to Sovik miał wątpliwości.$B$B<Nogg odchrząkuje.>$B$BSkoro plany są już w naszych rękach, to tylko kwestia czasu, aż rozgryziemy wszystkie gnomie innowacje, które złożyły się na tę machinę, i zrobimy z nich goblińskie innowacje w naszych nowych modelach rozdrabniaczy.', 0),
(2842, 'koKR', 'Piękność, co? Szczytowe osiągnięcie goblińskiej techniki transportowej – wybuchła raptem jakieś dwanaście razy.$b$bNie martw się, $N, wszystko już naprawiłem. Nie wybuchnie ci pod nogami, a jeśli nawet, to pójdzie szybko i bezboleśnie.', 0),
(2843, 'koKR', 'Gotowe! Kiedy zechcesz, po prostu wejdź na platformę.', 0),
(2904, 'koKR', 'Chyba należy ci się nagroda za to, że $gsprowadziłeś:sprowadziłaś; nam Kernobee w jednym kawałku, $N. Jeśli wrócisz do Gnomoregan, te rzeczy mogą dać ci przewagę potrzebną do pokonania tego nic niewartego zdrajcy, mechinżyniera Termowtyka.', 0),
(2922, 'koKR', 'Och, to cudownie! Dziękuję, $N! Natychmiast biorę się do pracy!!$B$BBiedny, biedny Techbot... Nie martw się. Naprawimy cię.$B$BNo, gdzie ja podziałem wtyczkę do mojego hydrolewarowego klucza obrotowego...', 0),
(2924, 'koKR', 'Masz je! Teraz mogę zacząć moje nowe eksperymenty!$B$BNie wiem, jak ci dziękować, $N! Dzięki twojej odwadze gnomia nauka zrobiła milowy krok naprzód!', 0),
(2925, 'koKR', 'Tak! Tak, potrzebuję pomocy przy wyprawie do Gnomoregan. A ty nadajesz się do tego jak nikt inny!', 0),
(2926, 'koKR', 'Świetna robota! Nadszedł czas, by wypróbować nową formułę. Jeśli zadziała, nie tylko wyleczy tego pojmanego trędowatego gnoma, ale i mnie odrośnie bujna czupryna! Odsuń się!', 0),
(2927, 'koKR', 'Myślałem, że utrata tej wspaniałej czupryny na pewno go wykończy, ale przeżył!$B$BStałem tuż obok niego, kiedy trafił go promień radiacji. Te przepiękne brązowe loki spadały na podłogę kępami! Całymi garściami! A zgroza tylko się pogłębiła, kiedy Gnoarnowi zupełnie odbiło! O tak, mówię ci, odbiło mu! Gnoarn dotknął łysej głowy z niedowierzaniem, a jego spojrzenie wołało o zemstę, $N! Potem cały swój gniew skierował przeciwko troggom!$B$B<Ozzie się wzdryga.>', 0),
(2929, 'koKR', 'Lubię myśleć, że ostatnim, co przeleciało mu przez głowę, kiedy padał na ziemię, była twoja stopa. Teraz, gdy Termowtyk nie żyje, nasze plany odbicia Gnomoregan są o krok bliżej urzeczywistnienia.', 0),
(2930, 'koKR', 'Udało ci się! $GZnalazłeś:Znalazłaś; pryzmatyczną kartę perforowaną i $godzyskałeś:odzyskałaś; utracone dane! Niezwykle, krytycznie, niezmiernie ważne dane, bez których nie moglibyśmy przeżyć ani chwili dłużej!$B$BGnomy długo będą pamiętać twoją przysługę, $N.', 0),
(2931, 'koKR', 'Organizuję wyprawy do Gnomoregan w celu wydobycia danych. Jeśli po to tu jesteś, to słuchaj uważnie!', 0),
(2945, 'koKR', 'Wkładasz pierścień do Błyskomatu 5200 i wrzucasz do szczeliny srebrną monetę.$B$BZ wnętrza maszyny dobiega bolesny zgrzyt, a całe urządzenie zaczyna gwałtownie podskakiwać. Można się tylko domyślać, co dzieje się z pierścieniem w środku...$B$BMaszyna nagle staje, obwieszczając koniec pracy prostym „Dzyń!”. Otwiera się komora na przedmioty, a w niej leży małe pudełko starannie przewiązane czerwoną kokardą. Wygląda na to, że Błyskomat 5200 pakuje też prezenty!', 0),
(2947, 'koKR', 'Pierścień, powiadasz? Zobaczmy... tak, a niech mnie, to ja zrobiłem ten pierścień.$B$BZanim Gnomoregan wyleciało w powietrze, miałem tam mały sklepik. Może to jeden z tych, które zostawiłem, kiedy brałem nogi za pas. To prosty wzór, zrobiłem kilka takich. Może należał do kogoś, komu nie udało się uciec.$B$BCzarnoryci go mieli? No, to dokłada nową warstwę spisku do dziewięciu innych, które już krążą. Może władze chciałyby o tym wiedzieć – na kimś takim jak ja to się tylko zmarnuje.$B$BA teraz wróćmy do pierścienia...', 0),
(2949, 'koKR', 'Pierścień z Gnomoregan? Zobaczmy... nie mój, ale ciekawy.$B$BTo, co się stało w Gnomoregan – nie mogło spotkać milszej bandy tępaków. Przez lata byli pośmiewiskiem, a teraz niemal z dnia na dzień budują lepsze machiny od nas?$B$BCzarnoryci mieli ten pierścień? To jeszcze ciekawsze! Wiesz, może gnomy ukradły ich szalone plany golemów i je przerobiły. Czarnoryci na pewno chcieliby się porządnie odegrać. Zdecydowanie warto to zbadać.$B$BA co do tego pierścienia...', 0),
(2951, 'koKR', 'Wkładasz przedmiot pokryty brudem i trzy srebrne monety do Błyskomatu 5200. Maszyna budzi się do życia i gorączkowo próbuje usunąć brud z nieznanego przedmiotu. Z jej trzewi dobiega głośne, gwałtowne łomotanie. Metalowy korpus bestii skrzypi i jęczy, przechylając się z boku na bok...', 0),
(2952, 'koKR', 'Równie szybko, jak ruszył, Błyskomat 5200 nagle staje. Z maszyny dobiega proste „dzyń”, a jej otwór rozkręca się ku górze. Wewnątrz Błyskomatu 5200 leży małe pudełko przewiązane kokardką. Najwyraźniej maszyna pakuje przedmiot, kiedy już pozbawi go brudu. Nawet jeśli nie zadziałała, przedmiot jest przynajmniej ładnie zapakowany.$B$BCóż, jest tylko jeden sposób, żeby sprawdzić, czy przedmiot został wyczyszczony...', 0),
(2953, 'koKR', 'Błyskomat 5200 budzi się do życia i kołysze się w przód i w tył. W środku bezbronny brud oblepiający włożony przedmiot jest miażdżony przez gnomi środek czyszczący.$B$BBłyskomat 5200 zatrzymuje się, obwieszczając to znajomym „dzyń!”. Komora na przedmioty rozkręca się, odsłaniając starannie zapakowane pudełko.', 0),
(2962, 'koKR', '<Ozzie przygląda ci się uważnie.> Imponujące, nadal masz wszystkie kończyny. A teraz zobaczmy, co to cudo potrafi!', 0),
(2997, 'koKR', 'Bądź $gpozdrowiony:pozdrowiona;, $N. Mam nadzieję, że Światłość wskaże ci prawdziwą ścieżkę i uchroni cię przed złem.', 0),
(3106, 'koKR', 'Zobaczysz pewnie też inne rzeczy, więc żebyś $gwiedział:wiedziała;, co i jak: krasnoludy, które w walce używają magii zamiast strzelby. Niektórzy z nas zaczęli czcić Świętą Światłość jak część ludzi, no i wreszcie, a jakże – troggi. Więcej o nich dowiesz się później, ale teraz musisz wiedzieć, że jestem tu, żeby ci pomóc.$b$bNauczę cię, co trzeba, żeby wyrósł z ciebie prawdziwy $c. Kiedy tylko uznasz, że potrzebujesz więcej szkolenia, wracaj do mnie, a zobaczę, co da się zrobić.', 0),
(3107, 'koKR', 'Ludzie wiele nas nauczyli o Świętej Światłości i o tym, jak ważny jest dla nich ich zakon... i jak ważny jest dla ochrony całego Azeroth. Wielce szanujemy to, jak głęboko jest zakorzeniony w tradycji i jak jedna postać, jedno poświęcenie, może przesądzić o tym, czy nastanie cierpienie, czy zbawienie.$B$BPrzez jakiś czas będziemy razem pracować. Kiedy tylko uznasz, że jesteś $ggotów:gotowa;, wracaj do mnie, a zobaczymy, czego jeszcze da się cię nauczyć. Nie możemy wypuścić cię w świat $gnieprzygotowanego:nieprzygotowaną;, prawda?', 0),
(3108, 'koKR', 'Jedno musisz zawsze pamiętać: trzeba szanować świat, w którym się żyje. Bestie, które zechcą walczyć u twego boku, blask twojej broni, ciężar twojej amunicji, ukąszenie mroźnego wiatru – wszystko to musisz znać na wylot.$B$BZrobię, co w mojej mocy, żeby ci pomóc, ale większość pracy zależy od ciebie. Kiedy tylko uznasz, że jesteś $ggotów:gotowa;, wróć i porozmawiaj ze mną. Będę cię szkolić, kiedy tylko zdołam.', 0),
(3109, 'koKR', 'Tak czy inaczej, kiedy zaczniesz węszyć po Zimnej Grani, pewnie w końcu przyda ci się jakieś szkolenie. Wracaj do mnie, kiedy tylko poczujesz, że go potrzebujesz, a nauczę cię tego, co wiem – tu jakiejś sztuczki, tam jakiegoś manewru. No wiesz, tego, co pozwala przeżyć i zarobić parę monet na boku.$B$BMiej też oko na naszych gnomich przyjaciół... dostało im się najgorzej, skoro Gnomoregan zostało... zniszczone. Potrzebują naszej pomocy, żeby poczuć się tu jak u siebie.', 0),
(3110, 'koKR', 'To ja mogę cię szkolić, kiedy zaczniesz poznawać Dolinę Zimnej Grani. Kiedy poczujesz, że jesteś $ggotów:gotowa;, wracaj do mnie, a zobaczymy, czy nie nauczyć cię nowego zaklęcia czy dwóch, żebyś $gmógł:mogła; bronić doliny przed tymi przeklętymi troggami.$B$BMasz po swojej stronie Światłość, a razem z nią całą Żelazną Kuźnię, $N... nikt nie wymaga, żebyś od razu $gstał:stała; się kimś wyjątkowym.', 0),
(3112, 'koKR', 'No, skoro to twoja główna dyrektywa, czy jak wy to tam teraz nazywacie, dałem słowo, że zrobię, co w mojej mocy, żebyś ty i twoi pobratymcy byli gotowi odbić swój dom... i dokładnie to zamierzam zrobić.$B$BKiedy tylko poczujesz, że jesteś $ggotów:gotowa;, wracaj do starego, poczciwego Thrana, a chętnie podzielę się z tobą swoją wiedzą. Szkolenie trochę kosztuje, ale nie będzie za drogo. Powodzenia.', 0),
(3113, 'koKR', 'Raczej trzymam się tu na uboczu, żeby nikt nas nie obwiniał, kiedy coś zginie, ale jeśli będziesz czegoś potrzebować, jakiegoś szkolenia czy czego tam, wracaj, kiedy zechcesz.$B$BTy i ja dobrze się rozumiemy. Wiemy, że koniec końców ufać można tylko rodzinie... a przecież właśnie tym tu jesteśmy, nie? Niezależnie od tego, że Gnomoregan zostało... zajęte, i od tego, co jeszcze na nas spadnie, mamy siebie nawzajem i możemy na sobie polegać. Prawda?', 0),
(3114, 'koKR', 'A, no tak! Sztuki tajemne... oczywiście.$b$bSłuchaj, $N, musisz wiedzieć jedno: nie pakuj się w zbyt wielkie kłopoty. Odłóż trochę grosza, żeby postawić mi piwo... albo kupić sobie jakieś zaklęcia. I trzymaj się, do licha, z dala od Gnomoregan. Poza tym miłego dnia! Będę tutaj, jeśli będziesz mnie potrzebować albo zechcesz się szkolić... czy coś.', 0),
(3115, 'koKR', 'Ale nic z tego nie ma znaczenia. Ważne jest to, że $gujrzałeś:ujrzałaś; własną Świętą Światłość! Wiesz, skąd naprawdę bierze się moc. Rozumiesz, że posiadanie własnych sprzymierzeńców jest o wiele... rozsądniejsze. Wyjątkowych sprzymierzeńców. Takich, którzy bez względu na zadanie będą posłuszni do ostatniego tchu.$b$bI tu wkraczam ja, $N. Mogę nauczyć cię podstaw tych szczególnych mocy. Odwiedzaj mnie często, a zrobię, co w mojej mocy, by nauczyć cię kolejnych zaklęć.', 0),
(3361, 'koKR', 'Hurra, $gznalazłeś:znalazłaś; je! Jesteś $gmoim prawdziwym wybawcą:moją prawdziwą wybawczynią;, $gprzyjacielu:przyjaciółko;! Proszę, to niewiele, ale weź to w podzięce za kłopot, jaki ci sprawiłem! Dziękuję!', 0),
(3364, 'koKR', 'Ach, dobrze, tego mi było trzeba. Pozwól, że zrobię sobie krótką przerwę i nacieszę się tym parzącym porannym naparem!', 0),
(3365, 'koKR', 'Świetnie, $N! Nie uwierzysz, ilu posłańców zapomina o czymś tak prostym jak oddanie kufla. Kufle nie rosną na drzewach, a przynajmniej tak mi mówią!$b$bMasz tu coś za fatygę. Jeszcze raz dzięki za pomoc.', 0),
(4126, 'koKR', '$GZnalazłeś:Znalazłaś; go! Dobra robota! Mam nadzieję, że porządnie $gprzetrzepałeś:przetrzepałaś; skórę tym Czarnorytym i Hurleyowi Czarnodechowi!$b$bGromowarowie są do twoich usług, $N. Jesteś $gbohaterem nad bohaterami:bohaterką nad bohaterkami;!', 0),
(4128, 'koKR', 'Pewnie, że jestem wściekły! Okradli mnie! Ukradli jeden z przepisów naszej rodziny! Jak śmieli! Jakbym nie miał dość powodów, żeby nienawidzić Czarnorytych! No, teraz... teraz to się doigrali!', 0),
(4601, 'koKR', 'Wkładasz przedmiot pokryty brudem i trzy srebrne monety do Błyskomatu 5200. Maszyna budzi się do życia i niemal gorączkowo próbuje usunąć brud z nieznanego przedmiotu. Z jej trzewi dobiega głośne, gwałtowne łomotanie. Metalowy korpus bestii skrzypi i jęczy, przechylając się z boku na bok...', 0),
(4602, 'koKR', 'To ustrojstwo wyróżnia się pośród gnomów, które bronią się przed szaleństwem panującym za drzwiami. Na małej tabliczce na urządzeniu widnieje napis „Błyskomat 5200”, a pod nim tekst:$B$B„Brud i osad niszczą twoje błyskotki? Błyskomat 5200 przywróci im błyskotastyczny blask! Włóż przedmiot, który chcesz wyczyścić, i wrzuć do szczeliny trzy srebrne monety. Daj Błyskomatowi 5200 chwilę na pracę i voilà! Twoje kosztowności wyjdą czyste i lśniące!”', 0),
(4603, 'koKR', 'Błyskomat 5200 budzi się do życia i kołysze się w przód i w tył. W środku bezbronny brud oblepiający włożony przedmiot jest miażdżony przez gnomi środek czyszczący.$B$BBłyskomat 5200 zatrzymuje się, obwieszczając to znajomym „dzyń!”. Komora na przedmioty rozkręca się, odsłaniając starannie zapakowane pudełko.', 0),
(4604, 'koKR', 'Błyskomat 5200 budzi się do życia i kołysze się w przód i w tył. W środku bezbronny brud oblepiający włożony przedmiot jest miażdżony przez gnomi środek czyszczący.$B$BBłyskomat 5200 zatrzymuje się, obwieszczając to znajomym „dzyń!”. Komora na przedmioty rozkręca się, odsłaniając starannie zapakowane pudełko.', 0),
(4605, 'koKR', 'Równie szybko, jak ruszył, Błyskomat 5200 nagle staje. Z maszyny dobiega proste „dzyń”, a jej otwór rozkręca się ku górze. Wewnątrz Błyskomatu 5200 leży małe pudełko przewiązane kokardką. Najwyraźniej maszyna pakuje przedmiot, kiedy już pozbawi go brudu. Nawet jeśli nie zadziałała, przedmiot jest przynajmniej ładnie zapakowany.$B$BCóż, jest tylko jeden sposób, żeby sprawdzić, czy przedmiot został wyczyszczony...', 0),
(4606, 'koKR', 'Równie szybko, jak ruszył, Błyskomat 5200 nagle staje. Z maszyny dobiega proste „dzyń”, a jej otwór rozkręca się ku górze. Wewnątrz Błyskomatu 5200 leży małe pudełko przewiązane kokardką. Najwyraźniej maszyna pakuje przedmiot, kiedy już pozbawi go brudu. Nawet jeśli nie zadziałała, przedmiot jest przynajmniej ładnie zapakowany.$B$BCóż, jest tylko jeden sposób, żeby sprawdzić, czy przedmiot został wyczyszczony...', 0),
(5541, 'koKR', 'Świetnie, więcej amunicji! Dostawa od starego Loslora w końcu dotarła! Może i spóźniona, ale jak mawiał mój dziadunio: lepiej późno niż wcale!$b$bWielkie dzięki, $N. Już mam kupców, którzy się na nią ostrzą!', 0),
(5625, 'koKR', 'Dobra robota, $n. Światłość na pewno w tobie mieszka.$B$BProszę, weź tę szatę. Będzie oznaką twojej roli w Kościele i pozwoli ludziom rozpoznać w tobie $gkapłana:kapłankę; – noś ją, jeśli chcesz.$B$BPóźniej czekają cię kolejne próby. Rób, co możesz, by poznać swoje zdolności i to, do czego jesteś $gzdolny:zdolna;. Spróbuj swoich sił w walce, najpierw raz czy dwa w pojedynkę, a potem z innymi podróżnikami.$B$BAle nie martw się... masz w sobie tyle mocy, ile tylko można mieć.', 0),
(5626, 'koKR', 'Och, więc przysłał cię Branstock, tak? Dobrze, dobrze! Ma rację, najwyższy czas, żebyś $gzrobił:zrobiła; o wiele większy krok w stronę Światłości. To zahartuje twój charakter i uczyni cię $gsilniejszym:silniejszą;... a tego będziesz potrzebować bardziej niż czegokolwiek: siły ciała... siły woli.', 0),
(6064, 'koKR', 'Wiem, wiem, zastanawiasz się, co dalej, co?!', 0),
(6084, 'koKR', 'Kiedy uznam, że dość się już $gnauczyłeś:nauczyłaś;, dam ci możliwość wybrania dowolnego zwierzaka.', 0),
(6085, 'koKR', 'Proszę bardzo, $N. Teraz dam ci moc oswajania bestii oraz przywoływania ich i odprawiania, kiedy tylko zechcesz.$B$BZnajdź sobie dobrego, wiernego zwierzaka i udanych łowów!', 0),
(6086, 'koKR', 'Nowy rekrut, co? Widzę, że masz przed sobą drogę do zostania $gwielkim łowcą:wielką łowczynią;.$B$BTak, mogę przekazać ci umiejętności potrzebne do szkolenia i prowadzenia twojego zwierzaka. Nie tylko nauczysz go nowych zdolności, ale też zdołasz go karmić, a nawet wskrzesić, jeśli padnie w walce.$B$BPamiętaj, że najwięcej zyskasz ze swojego nowego zwierzaka, jeśli będziesz go szanować i dobrze traktować. W zamian zwierzak będzie twoim najwierniejszym przyjacielem.', 0),
(25199, 'koKR', '$GPrzeszedłeś:Przeszłaś; to w jednym kawałku? Twarde z ciebie tryby, twardsze, niż myślałem, $N!', 0),
(25212, 'koKR', 'Fantastyczna robota!$B$BDane, które dostałem, pokazują, że poziom promieniowania mieści się w pełni w zakresie bezpieczeństwa naszych kombinezonów. To świetna wiadomość!', 0),
(25229, 'koKR', 'To najlepsza grupa kandydatów na pilotów, jaką udało ci się znaleźć?$B$BNo dobrze, zobaczę, co da się zrobić. Słynę z tego, że nawet najbardziej pogiętą kupę trybów potrafię zmienić w gładko chodzącą machinę bojową, a z tą bandą nie spodziewam się niczego gorszego.$B$BCóż, chyba czas brać się do roboty!', 0),
(25283, 'koKR', 'O rety. Aż tak różnie zareagowali?$b$bNie całkiem tego się spodziewałem, ale chyba mam przemowę, która się nada.$b$bTylko niech sobie przypomnę, gdzie ją położyłem...', 0),
(25285, 'koKR', 'Hej, no proszę! Nie $growerwało:rozerwało; cię na strzępy!', 0),
(25286, 'koKR', 'Toby skończył przemowę? Pokaż...$b<Czyta przemowę> Na pompujące tłoki! Cóż za fantastyczna przemowa! Wiedziałem, że Toby dobrze pisze, ale to chyba najlepsze, co kiedykolwiek napisał.$bCzas wysłać cię na pole bitwy.', 0),
(25287, 'koKR', 'A więc to ostateczna wersja? Niech no rzucę okiem...', 0),
(25289, 'koKR', 'Hmm... czyli serwomechanizm lewej nogi uruchamiał prawą? Ale przecież widziałem, jak rusza się lewa noga...$B$BEch, szczegóły. Zajmę się tym później, ale dwie z trzech rzeczy zadziałały: to wcale nie najgorzej!$B$BDzięki, że to dla mnie $gsprawdziłeś:sprawdziłaś;, $N.', 0),
(25295, 'koKR', 'Hmm... czyli kule miały spory rozrzut?$B$BDla niektórych to byłby problem... ale ja widzę w tym ukrytą zaletę!$B$BNasi wrogowie będą biegać we wszystkie strony, więc przy odrobinie rozrzutu kierowcy czołgów nie będą musieli brać poprawki na cel!', 0),
(25393, 'koKR', 'Niech to! Musieliśmy się wycofać. Ale Termowtyk przegrał i dobrze o tym wie... kupił sobie tylko trochę czasu. Utrzymujemy powierzchnię, a kiedy promieniowanie opadnie, uderzymy znowu i odbijemy Gnomoregan siłami dwa razy większymi niż te.', 0),
(25500, 'koKR', 'To przemowa od Toby\'ego? Fantastycznie!$bRekrucie, $gzrobiłeś:zrobiłaś; wszystko, o co mogliśmy prosić, i Armia Gnomoregan ci dziękuje!$bNasz oddział uderzeniowy wyrusza właśnie do Gnomoregan, a bez twojej pomocy nie byłoby to możliwe. W podzięce za wszystko chcielibyśmy, żebyś $gwstąpił:wstąpiła; do Rezerwy Gnomoregan!$bPłacą tam niezbyt dobrze, ale dostajesz ten szykowny hełm. Zachowaj go, może się kiedyś przydać!', 0);
INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES
(170, 'koKR', 'Uparte z nich paskudy, co?', 0),
(179, 'koKR', 'Wilki sprawiają ci kłopot? Lepiej trzymaj się z dala od kłów, pazurów i innych ostrych kawałków, co?', 0),
(182, 'koKR', 'Z tego, czego się dowiedziałem, te trolle pochodzą z klanu Mroźnej Grzywy. Obawiam się, że nie wiem o nich nic więcej, co mogłoby ci się przydać, $N.', 0),
(183, 'koKR', 'Jak idą łowy?', 0),
(218, 'koKR', '$N! I jak, udało się?', 0),
(233, 'koKR', 'Tak? Masz coś dla mnie?', 0),
(234, 'koKR', 'W czym mogę ci pomóc?', 0),
(282, 'koKR', 'Witaj! Uważaj, $N, tunel do Dun Morogh roi się od troggów i nie jest bezpieczny dla podróżnych.$b$bJeśli nie masz w Dun Morogh pilnych spraw, muszę cię prosić, żebyś $gzostał:została; w Kowadlinie, dopóki tunel nie stanie się bezpieczniejszy.', 0),
(287, 'koKR', 'Nie możesz jej znaleźć? Moje wskazówki były bardzo jasne! Nie mamy wiele czasu, musisz się pospieszyć! Nie wracaj, dopóki nie znajdziesz jaskini.', 0),
(291, 'koKR', 'Hmm... zdaje się, że moi strażnicy coraz mniej wybrzydzają przy wpuszczaniu petentów. No, czego chcesz? Tylko szybko.', 0),
(308, 'koKR', 'Hmpf! Tyle tu na dole trunków, a ja mam surowy zakaz ich tykania. Gdybym tylko mógł skosztować choć trochę naszego piwa gromu... od razu by mi się w głowie rozjaśniło, słowo daję!', 0),
(310, 'koKR', 'Data na tej beczce wskazuje, że wkrótce zostanie napoczęta.', 0),
(311, 'koKR', 'Udało się podmienić?', 0),
(312, 'koKR', 'Udało ci się dostać do mojej spiżarni, $N?', 0),
(313, 'koKR', 'Hej, $N. $GByłeś:Byłaś; już w Siwej Norze? Te wendigo potrafią być groźne.', 0),
(314, 'koKR', 'Vagash wciąż terroryzuje stado! Proszę, pomóż nam i zabij tę nędzną bestię.', 0),
(315, 'koKR', 'Masz to połyskliwe ziele? Mam już prawie gotową warkę stouta i chcę spróbować dorzucić ziele do tej mieszanki.', 0),
(317, 'koKR', 'Przygotowania idą dobrze. A jak twoje łowy?', 0),
(319, 'koKR', '$GZająłeś:Zajęłaś; się już tymi dzikimi zwierzętami?', 0),
(320, 'koKR', '$GZdobyłeś:Zdobyłaś; ten „Wieczny blask”?', 0),
(384, 'koKR', 'Potrzebuję sześciu żeber dzika skalnego i kufla słodu „Rapsodia”, $N.', 0),
(400, 'koKR', 'Hm? Jak na pilota machiny oblężniczej wyglądasz trochę za młodo. Ale mniejsza z tym... trzeba ci coś naprawić?$B$BTo weź numerek i rozgość się. Pracuję teraz nad kilkoma machinami i przez najbliższe dni nie będę miał czasu na kolejne zlecenie.$B$BA może $gprzyszedłeś:przyszłaś; w innej sprawie...?', 0),
(412, 'koKR', 'Rekombobulator ruszy, gdy tylko będziemy mieli dość trybików restabilizacyjnych i żyromechanicznych zębatek.', 0),
(413, 'koKR', 'Witaj! A co cię sprowadza aż tutaj?$B$BMam nadzieję, że coś ekscytującego. Od kilku dni nie miałem porządnej bitki, a ta beczka piwa prawie wyschła...', 0),
(414, 'koKR', 'Pozdrowienia! Witaj w Thelsamarze – każdy $c jest tu mile widziany!', 0),
(417, 'koKR', 'Witaj, $N. Masz wieści o moim przyjacielu Hildelve?', 0),
(420, 'koKR', 'Jak się masz? Może napijesz się ze mną? W tym zimnie niewiele więcej jest do roboty.', 0),
(432, 'koKR', 'Aż mnie skręca ze złości! Grrr...', 0),
(433, 'koKR', 'Jeśli zdołamy usunąć troggi z Kamieniołomu Gol\'Bolar, będzie to pierwszy z wielu kroków, które musimy podjąć, by pozbyć się tej plagi.', 0),
(466, 'koKR', 'Gdzie ta ruda, $N?!', 0),
(1679, 'koKR', 'Udało się podmienić?', 0),
(1784, 'koKR', 'No i $gwróciłeś:wróciłaś;! Cieszę się, że cię widzę, $N. Rany mi się zagoiły i jestem prawie gotów wracać nad Jezioro Łoża Helma, jak tylko przekonam żonę, że nic mi nie będzie.', 0),
(2160, 'koKR', 'Witaj! Wejdź, usiądź przy ogniu i rozgrzej się kuflem piwa.', 0),
(2239, 'koKR', 'Podobał ci się smród trędowatych gnomów? Pytam tylko dlatego, że masz na twarzy jakiś szalony uśmiech.$B$BJakie wieści przynosisz od Onina?', 0),
(2841, 'koKR', 'Nie widzę żadnych planów. $GSchowałeś:Schowałaś; je gdzieś na sobie, czy tylko stoisz tu, żeby mnie drażnić?$b$b', 0),
(2843, 'koKR', 'Gotowe!', 0),
(2904, 'koKR', 'Hę? Kernobee żyje??', 0),
(2922, 'koKR', '$GZnalazłeś:Znalazłaś; Techbota? Udało się odzyskać jego rdzeń pamięci??', 0),
(2924, 'koKR', 'Masz sztuczne esencje?', 0),
(2926, 'koKR', 'Nie widzisz, że próbujemy tu wyleczyć cały gatunek gnomów??! Potrzebujemy więcej zielonej poświaty!', 0),
(2929, 'koKR', 'Czy zadanie wykonane? Błagał o łaskę? O litość??', 0),
(2930, 'koKR', 'Masz pryzmatyczną kartę perforowaną??', 0),
(2945, 'koKR', 'Gnomie ustrojstwo przed tobą ma tabliczkę z napisem „Błyskomat 5200”. Z instrukcji pod tabliczką wynika, że maszyna służy do szorowania przedmiotów z brudu. Ma szczelinę na monety – gdy przedmiot znajdzie się w środku, trzeba wrzucić trzy srebrne monety, by rozpocząć proces.$B$BPierścień pokryty brudem, który $gznalazłeś:znalazłaś; wcześniej, wydaje się w sam raz do wypróbowania tej maszyny!', 0),
(2947, 'koKR', 'Hej, spokojnie, $gkolego:koleżanko; – jestem bardzo ważnym przedsiębiorcą! Na pewno posłaniec po prostu spóźnia się z czynszem... chwila... przecież ty nie jesteś moim właścicielem.$B$BNo jasne, że nie – głuptas ze mnie! $GPrzyszedłeś:Przyszłaś; do mnie, bo szukasz najlepszego jubilera w całej Żelaznej Kuźni, takiego, który NIE robi PRZEKLĘTYCH przedmiotów! Tak!$B$BEee... czego potrzebujesz?', 0),
(2949, 'koKR', 'Można by pomyśleć, że sami znajdziemy sposób, żeby przebić te plugawe gnomiszcza. Założę się nawet, że to one ukradły nam tę machinę! Bah, te tłuste, umorusane... eee, tak? Czegoś potrzebujesz?', 0),
(2951, 'koKR', 'Wygląda na to, że urządzenie potrzebuje jakiegoś przedmiotu pokrytego brudem do wyczyszczenia i trzech srebrnych monet, żeby ruszyć. Jeśli będzie jedno i drugie, Błyskomat 5200 powinien zadziałać...', 0),
(2953, 'koKR', 'Błyskomat 5200 jest pusty i czeka na przedmiot pokryty brudem do wyczyszczenia oraz trzy srebrne monety na start!', 0),
(2962, 'koKR', 'Hmm, nie świecisz. To dobry znak.', 0),
(3106, 'koKR', 'Psiakrew, ale dziś zimno, co? Jakby ten śnieg nigdy nie miał zniknąć, $N.$b$bPewnie już $gzauważyłeś:zauważyłaś;, że w naszym mieście mieszkają teraz gnomy. To dlatego, że same wysadziły się z własnego domu. Nie rozpowiadaj tego, ale trudno mi ich winić – chyba też sięgnąłbym po materiały wybuchowe, gdyby Żelazną Kuźnię opanowali Czarnoryci albo inne paskudztwo.', 0),
(3107, 'koKR', 'No proszę, jesteś! I to w samą porę. W Dolinie Zimnej Grani i dalej jest mnóstwo do zrobienia. Będę potrzebował twojej pomocy tak samo jak ty mojej!$B$BNależysz teraz do rycerzy Srebrnej Dłoni, bądź $ggotów:gotowa; odegrać tę rolę.', 0),
(3108, 'koKR', 'Jesteś! Dobrze słyszeć! Założę się, że nawet nie $gmusiałeś:musiałaś; mnie tropić, żeby tu trafić. Ha, ha!$B$BNasz fach jest mocno zakorzeniony w tradycji, $N. Poznawanie ścieżek tej ziemi. Tropienie niedźwiedzia przez góry. Nawet samo przetrwanie wyłącznie dzięki własnemu sprytowi wymaga sporo odwagi i przebiegłości. Myślisz, że dasz radę?', 0),
(3109, 'koKR', 'Jesteś! Świetnie!$B$BOstatnio sporo się u nas dzieje, więc cieszę się, że w naszych szeregach przybył ktoś jeszcze z klanu Żelaznej Kuźni. Jak na mój gust zbyt wielu z nas zwraca się ku mocom tajemnym i boskim. Nic do nich i do ich przekonań nie mam, ale nie ma to jak zimne ostrze w dłoni i cień, który skryje cię przed światłem, rozumiesz?', 0),
(3110, 'koKR', 'Ach! Jesteś, $N! Wspaniale!$B$BJuż miałem powiedzieć, że zaczynam tracić wiarę, że w ogóle dotrzesz... łapiesz? Tracić wiarę? To żart, $gchłopcze:dziewczyno;... eee, nieważne. I tak nie $gprzyszedłeś:przyszłaś; tu słuchać moich kiepskich dowcipów.', 0),
(3112, 'koKR', 'Ach, no tak, kolejna notatka, $gkolejny:kolejna; $R z misją... jakie to urocze.$B$BNie, nie, nie drwię z ciebie, maluchu. Trzeba szanować twój upór, to pewne jak amen w pacierzu. Też byłbym wściekły, gdyby Żelazną Kuźnię zajęli Czarnoryci, więc nie myśl, że nie współczuję ci w twojej doli...', 0),
(3113, 'koKR', 'Cieszę się, że $gdostałeś:dostałaś; moją wiadomość i tu $gzajrzałeś:zajrzałaś;. Wybacz, że udawałem, jakby to była notatka od twoich przełożonych... bez urazy. Po prostu wiedziałem, że ty i ja, razem z innymi z naszej profesji, musimy trzymać się razem.$B$BNiewielu uważa, że to najlepsze, co może być, kiedy twój lud i mój lud gnieżdżą się w jednym mieście, ale myślę, że jakoś się dogadamy. Co o tym myślisz?', 0),
(3114, 'koKR', 'No, o co chodzi? Mów głośniej, jeśli łaska. Po paru piwach nie za dobrze słyszę.', 0),
(3115, 'koKR', 'Wspaniale! Najwyraźniej $gdostałeś:dostałaś; moją notatkę.$b$bNie zwracaj uwagi na otaczających cię głupców, $N. Święta Światłość?! Miecz i tarcza?! To nie są ścieżki dla umysłów tak otwartych jak nasze. Spójrz, co „zwyczajna” magia zrobiła z naszym domem. Razem z tymi przeklętymi majsterkowiczami niemal doprowadziła do wymarcia naszej rasy. A teraz musimy zdać się na krasnoludy – które wolą się bratać z ludźmi, niż pomóc nam odbudować nasz dom. Jesteśmy jak obywatele drugiej kategorii. $GWidziałeś:Widziałaś;, jak one na nas patrzą?', 0),
(3361, 'koKR', 'Ojej, $N, to miasteczko zupełnie nie nadaje się dla kogoś takiego jak ja. Jest tu tyle paskudnych stworów, ile było w Gnomoregan przed wypadkiem!$b$bMasz moje rzeczy? Jeśli nie, to kto wie, co te trolle z nimi teraz zrobiły...', 0),
(3364, 'koKR', 'Tak, jestem Durnan Futrokrój. Masz coś dla mnie?', 0),
(3365, 'koKR', 'Mam nadzieję, że parzący poranny napar dotarł do Durnana na czas! Pamiętasz, żeby oddać mi kufel?', 0),
(4126, 'koKR', 'Masz przepis, $N? Nie mogę znieść myśli, że te krasnoludy z klanu Czarnorytych piją trunek mojej rodziny!', 0),
(4601, 'koKR', 'Wygląda na to, że urządzenie potrzebuje jakiegoś przedmiotu pokrytego brudem do wyczyszczenia i trzech srebrnych monet, żeby ruszyć. Jeśli będzie jedno i drugie, Błyskomat 5200 powinien zadziałać...', 0),
(4602, 'koKR', 'Włóż przedmiot pokryty brudem do Błyskomatu 5200 i pamiętaj, że do uruchomienia maszyny potrzebujesz trzech srebrnych monet.', 0),
(4603, 'koKR', 'Błyskomat 5200 jest pusty i czeka na przedmiot pokryty brudem do wyczyszczenia oraz trzy srebrne monety na start!', 0),
(4604, 'koKR', 'Błyskomat 5200 jest pusty i czeka na przedmiot pokryty brudem do wyczyszczenia oraz trzy srebrne monety na start!', 0),
(5541, 'koKR', 'Mam nadzieję, że nie przychodzisz po amunicję, bo prawie mi się skończyła!', 0),
(5625, 'koKR', '$GZnalazłeś:Znalazłaś; już Dolfa, $N?$B$BPewnie już się o tym $gprzekonałeś:przekonałaś;, ale nasza zdolność leczenia bardzo się przydaje. Nie tylko możemy opatrywać rannych, ale jesteśmy też niezbędni do przetrwania tych wszystkich niedoszłych bohaterów, którzy próbują wyrobić sobie imię. Dzięki Wytrwałości, która pozwala przyjąć więcej ciosów, i naszej magii uzdrawiania, która utrzymuje ich przy życiu, nie ma rzeczy, której nie zdołalibyśmy pokonać!', 0),
(5841, 'koKR', 'Witaj! Miło cię poznać!$B$BWidzę, że masz specjalny bon. Daj mi go, a dostaniesz coś w zamian.', 0),
(6064, 'koKR', 'Bez obaw, $gchłopcze:dziewczyno;! Zanim wybierzesz tego jednego, wypróbujesz jeszcze kilka.', 0),
(6084, 'koKR', 'Co sądzisz o lamparcie śnieżnym, $N?', 0),
(6085, 'koKR', '$GOswoiłeś:Oswoiłaś; już lodopazurego niedźwiedzia?', 0),
(25283, 'koKR', 'Daj mi znać, która działa, dobrze?', 0);
INSERT INTO `quest_greeting_locale` (`ID`, `type`, `locale`, `Greeting`, `VerifiedBuild`) VALUES
(714, 0, 'koKR', 'Witaj, $N! Piękny dzień na polowanie, prawda? Mnie samemu nieźle się ostatnio szczęści z dzikami. Może też chcesz spróbować?', 0),
(786, 0, 'koKR', 'Witaj, $gchłopcze:dziewczyno;. Jestem Grelin Białobrody. Badam zagrożenie, jakie stwarza rosnąca liczba trolli w Dolinie Zimnej Grani. Co ustaliłem? Cóż, to trochę niepokojące...', 0),
(1254, 0, 'koKR', 'Troggi! Przysięgam, bogowie umieścili je w tej krainie tylko po to, żeby mnie dręczyć! Cztery cale w głąb kopalni, a potem przez troggi dwie stopy do tyłu!', 0),
(1267, 0, 'koKR', 'Witaj w Gorzelni Gromowarów, którą założył mój kochany staruszek, Arkilus Gromowar. Prowadzę ją, odkąd kilka żniw temu mój starszy brat, Ponurogorzał, przepadł gdzieś w pijackim zamroczeniu.', 0),
(1374, 0, 'koKR', 'Przeklęta Liga Piwowarów! Mają dostęp do najlepszych składników, a my tu musimy wydrapywać ziarno i chmiel!$B$BAż się prosi, żeby wymierzyć im sprawiedliwość o gorzkim posmaku...', 0),
(1377, 0, 'koKR', 'Prowadzenie czołgu parowego nie jest dla każdego. Trzeba mieć żelazny chwyt i stalowe nerwy... na szczęście mam jedno i drugie! A ty? Z jakiego jesteś kruszcu? Chcesz mi to udowodnić?', 0),
(1977, 0, 'koKR', 'Od urodzenia wychowywano mnie i kształcono do służby publicznej. Głos ludu. Moją siłą nie był oręż ani rzemiosło, lecz słowo i perswazja.', 0);
