INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES
(74, 'koKR', 'DZIEŃ PIERWSZY\n\nDotarliśmy dziś z uczniem do Doliny Zimnej Grani. Przeprawa przez jaskinię minęła w większości bez przygód. Rozbiliśmy obóz w sporej odległości od jaskini, w której podobno zebrały się trolle.\n\nDZIEŃ DRUGI\n\nPrzeklęte wycie wilków niemal nie dało mi spać całą noc.\n\nZa kilka dni będę miał nowe ubranie z wilczych skór.\n\nChłopak wdał się dziś w bójkę z troggiem, stawił mu opór i\n', 0),
(80, 'koKR', 'Grelinie, mam mało czasu, a wiele spraw go pochłania. Mam nadzieję, że twoje śledztwo w sprawie trolli nie będzie jedną z nich. Dlatego pozwalam ci posłużyć się moją władzą, by rozprawić się z trollami w dowolny sposób, jaki uznasz za konieczny, tym bardziej jeśli znajdziesz szybkie rozwiązanie. Magni Miedziobrody ', 0),
(81, 'koKR', 'zdołał pokonać tego szpetnego bydlaka, ale teraz opatruje paskudną ranę na ramieniu. Wygląda na to, że przez jakiś czas sam będę musiał odwalać całą robotę.$b$bDZIEŃ TRZECI$b$bZimno. Około południa trochę sypnęło śniegiem.$b$bDZIEŃ CZWARTY$b$bChłopak wrócił dziś w dobrym humorze, więc po raz pierwszy przyjrzeliśmy się trollom. Mroźna Grzywa, powiedziałbym, sądząc po znakach na ich skórze i rozmaitych błyskotkach, które mieli na sobie.', 0),
(82, 'koKR', 'DZIEŃ PIĄTY$b$bKazałem chłopakowi pilnować obozu, a sam zakradłem się do jaskini i rozejrzałem się. Liczba trolli jest nieco niepokojąca. Jeśli jaskinia ma zostać oczyszczona z tej plagi, być może trzeba będzie wezwać górskich strażników w pełnej sile.$b$bZauważam, że ostatnio nic nie pisałem o troggach. Pojawiają się w okolicy w coraz większej liczbie, ale są tak prymitywne, że nie stanowią wielkiego zagrożenia. Czas pokaże, czy tak jest naprawdę.', 0),
(83, 'koKR', 'I od prawie tygodnia ani kropli piwa.$b$bDZIEŃ SZÓSTY$b$bZnowu zimno. Pada śnieg. Trolle. Brak piwa.$b$bDZIEŃ SIÓDMY$b$bBiały śnieg pod nogą,$bNad głową błękity,$bWilki wyją srogo,$bKufel wciąż niepity.$b$bDZIEŃ ÓSMY$b$bTrolle to być może nie tak duży problem, jak początkowo sądziliśmy. Jest ich', 0),
(84, 'koKR', 'sporo, ale nie są dobrze uzbrojone ani zorganizowane. Niewielki pokaz siły powinien w zupełności wystarczyć, by uporać się z zagrożeniem, jakie stanowią. ', 0),
(86, 'koKR', 'Raport o sytuacji trolli z Mroźnej Grzywy na terenie Doliny Zimnej Grani i w jej okolicach\n\nSporządził Grelin Białobrody, specjalny wysłannik Senatu\n\nNa podstawie czasu, który spędziłem na obserwowaniu ruchów trolli z Mroźnej Grzywy w rejonie Doliny Zimnej Grani, ustaliłem, że nie stanowią one wielkiego zagrożenia dla krasnoludzkich osad w okolicy. Co więcej, zagrożenie to można usunąć przy niewielkim dodatkowym wsparciu armii. Z pomocą górskich strażników stacjonujących już w', 0),
(87, 'koKR', 'Dolinie Zimnej Grani oraz najemników (opłaconych z funduszy wydzielonych przez Senat przed moim wysłaniem),\n jestem pewien, że problem zostanie wkrótce rozwiązany. \n\nDziałania te zatwierdzono na mocy upoważnienia udzielonego mi przez króla Miedziobrodego.', 0),
(88, 'koKR', 'Raport o sytuacji trolli z Mroźnej Grzywy na terenie Doliny Zimnej Grani i w jej okolicach$b$bTrolle w Dun Morogh skupiają się głównie w Warowni Mroźnych Grzyw, górskiej jaskini przy zachodniej granicy. Jest ich dość, by budzić pewien niepokój, jednak wydają się bardziej niż zadowolone z pozostawania w swojej jaskini. Bez wątpienia dlatego, że nie chcą znów ściągnąć na siebie gniewu krasnoludów i ryzykować całkowitej zagłady. Ich działania można co najwyżej uznać za obronę terytorium i', 0),
(89, 'koKR', 'jestem przekonany, że nie stanowią dla nas realnego zagrożenia, dopóki nie wkraczamy na ich teren. Może się to nie spodobać krasnoludzkiej ludności, ale wobec rozproszenia sił wojskowych rozsądnie byłoby odsunąć wytępienie trolli na dalszy plan i nadal skupić się na zagrożeniu ze strony troggów i Czarnorytych.$b$bW załączeniu znajdziesz też kopię raportu mojego brata Grelina z Kowadlina.$b$bPodpisano,$bSenir Białobrody', 0),
(90, 'koKR', 'Raport o sytuacji trolli z Mroźnej Grzywy na terenie Doliny Zimnej Grani i w jej okolicach$b$bSporządził Grelin Białobrody, specjalny wysłannik Senatu$b$bNa podstawie czasu, który spędziłem na obserwowaniu ruchów trolli z Mroźnej Grzywy w rejonie Doliny Zimnej Grani, ustaliłem, że nie stanowią one wielkiego zagrożenia dla krasnoludzkich osad w okolicy. Co więcej, zagrożenie to można usunąć przy niewielkim dodatkowym wsparciu armii. Z pomocą górskich strażników stacjonujących już w', 0),
(91, 'koKR', 'Dolinie Zimnej Grani oraz najemników (opłaconych z funduszy wydzielonych przez Senat przed moim wysłaniem),\n jestem pewien, że problem zostanie wkrótce rozwiązany.$b$bDziałania te zatwierdzono na mocy upoważnienia udzielonego mi przez króla Miedziobrodego.', 0),
(229, 'koKR', 'Dzień 1\n\nMój czołg jest zepsuty, ale wiem, że ruda chironu jest gdzieś w tych wzgórzach. Kazałem Młotostopemu zostać i pilnować naszych czołgów.\n\nKontynuuję poszukiwania sam. Jeśli nie wrócę, ten dziennik będzie moim ostatnim testamentem.\n\n--Buron Hildelve, pilot\nBrygada Parowa Żelaznej Kuźni', 0),
(230, 'koKR', 'Dzień 2\n\nSzukam dalej, a rudy ani śladu. Zaczynam się zastanawiać, czy Kamiennotryb nie wymyślił tej plotki o rudzie dla żartu. Jeśli tak, to jak tylko wrócę do Składu Steelgrilla, rozłupię mu czaszkę!\n\nKiedy wieczorem rozbijałem obóz, usłyszałem warczenie odbijające się echem po kanionach. \n\nTo nie wilk. Może niedźwiedź.', 0),
(231, 'koKR', 'Dzień 3\n\nWarczenie nie ustawało przez całą noc i przez cały dzień szło za mną, rozpraszając mnie w poszukiwaniach rudy. Chyba śledzi mnie niedźwiedź!\n\nOby podszedł bliżej. Wbiję mu kilof w łeb!', 0),
(232, 'koKR', 'Dzień 4\n\nKończą mi się zapasy. Jedzenia mam jeszcze sporo, ale nie planowałem tak długiego pobytu w dziczy z dala od czołgu i wziąłem ze sobą tylko dwie baryłki piwa.\n\nOd dwóch nocy nie śpię, słuchając tego przeklętego warczenia, i prawie opróżniłem baryłki do dna!\n\nJutro będę musiał wrócić do Młotostopego i naszych czołgów parowych. Nie chcę się tu zgubić bez kropli trunku.', 0),
(233, 'koKR', 'Dzień 5\n\nPrzeklęty niedźwiedź mnie załatwił! Zaatakował mnie w południe, z rykiem szarżując od tyłu.\n\nGdyby nacierał od nawietrznej, poczułbym go z daleka – jego smród był okropny! Sam odór jego parszywego futra i zgniły oddech omal nie zwaliły mnie z nóg!\n\nOdparłem bestię, ale porządnie pogryzła mi nogę. Teraz nie mogę się ruszyć, piwo się skończyło, a tej rudy nigdy nie znalazłem. Niech to szlag!', 0),
(234, 'koKR', 'Dzień 6\n\nNiedźwiedź jeszcze nie wrócił – musiałem mu nieźle dołożyć! Ale wciąż słyszę jego warczenie. Chyba czeka, aż umrę!\n\nKtokolwiek znajdzie tę księgę, mam dla ciebie zadanie. Zabij tego parszywego niedźwiedzia. Zabij go i zanieś tę księgę mojemu przyjacielowi Młotostopemu. Będzie chciał wiedzieć, co się stało.\n\nI weź moją zbroję. Przyda ci się przeciwko staremu Parchopazurowi!', 0),
(812, 'koKR', 'Brudne troggi tak łatwo oszukać. Ich nienawiść do naszych pobratymców sprawia, że jeszcze łatwiej nimi kierować i używać ich jak pionków. Dziwi mnie, że w ogóle udało się zawrzeć jakiś sojusz, ale nasi pobratymcy są dla ich istnienia znacznie większym zagrożeniem... przynajmniej na razie.$B$BKiedy jednak zaczną się ataki, obie strony będą osłabione i wystawione na nasze własne uderzenie. Zajmijcie zagrodę na południe od Jeziora Łoża Helma i czekajcie na dalsze rozkazy.$B$BŻelazna Kuźnia będzie nasza.', 0),
(1131, 'koKR', 'SUPERKRYTYCZNA, POTRÓJNIE ZASZYFROWANA KARTA DANYCH\n\n01010100 01101000 01110010 01100001 01101100 01101100 00100000 01100001 01101110 01100100 00100000 01001010 01100001 01101001 01101110 01100001 00100000 01110011 01101001 01110100 01110100 01101001 01101110 01100111 00100000 01101001 01101110 00100000 01100001 00100000 01110100 01110010 01100101 01100101 00101100 00100000 01001011 00101101 01001001 00101101 01010011 00101101 01010011 00101101 01001001 00101101 01001110 00101101 01000111', 0),
(1194, 'koKR', 'Poziom tajności tych danych jest TAK wysoki, że czeka na wynalezienie nowej liczby, która by go opisała!', 0),
(1331, 'koKR', '01001101 01100101 01110011 01110011 01100001 01100111 01100101 00100000 01110100 01101111 00100000 01000011 01100001 01110011 01110100 01110000 01101001 01110000 01100101 00111010 00100000 01111001 01101111 01110101 01110010 00100000 01101100 01100001 01110101 01101110 01100100 01110010 01111001 00100111 01110011 00100000 01110010 01100101 01100001 01100100 01111001 00100000 01100110 01101111 01110010 00100000 01110000 01101001 01100011 01101011 01110101 01110000 00101110', 0),
(2433, 'koKR', 'Założę się, że $gspodziewałeś:spodziewałaś; się zwykłego listu od króla czy kogoś w tym rodzaju. Cóż, powiedzmy, że znam się trochę na podrabianiu listów i chciałem mieć pewność, że ten do ciebie dotrze. Nie mogę przecież zwracać na siebie uwagi, prawda?$B$BZaszyłem się w Kowadlinie – znajdziesz mnie przy palenisku. Kiedy będziesz $ggotów:gotowa;, przyjdź ze mną porozmawiać. Chcę się tylko przedstawić, póki mamy czas.$B$B-Solm Hargrin, nauczyciel łotrów', 0),
(2435, 'koKR', '$gBracie:Siostro;, mam nadzieję, że ta runa zastanie cię w dobrym zdrowiu. Chciałem tylko dać ci znać, że jestem w Kowadlinie nad Doliną Zimnej Grani.$B$BWiem, jak ważne jest, żebyśmy trzymali się razem, a w tych czasach kruchego pokoju coraz ważniejsze staje się to, by mieć swoich w pobliżu. Poszukaj mnie, kiedy znajdziesz chwilę. $B$B-Solm Hargrin, nauczyciel łotrów ', 0),
(2440, 'koKR', 'UWAGA:$BMasz natychmiast zgłosić się do Thrana Khormana. Przebywa w budynku A3, przez miejscowych zwanym Kowadlinem. Po nawiązaniu kontaktu z Khormanem przystąpisz do przygotowań do nadchodzącej wojny – wojny o odzyskanie naszego domu, Gnomoregan!$B$BWszystkie wysiłki i kluczowe zadania mają służyć realizacji tej dyrektywy. Po jej wykonaniu otrzymasz nowe zadanie. ', 0),
(2442, 'koKR', 'Na brodę Magniego, jest wiele do omówienia, a mało czasu, $N. Znajdź mnie jak najszybciej w Kowadlinie, z którego widać Dolinę Zimnej Grani. Musimy zaczynać.$B$BMógłbym ci opowiedzieć o całej masie spraw, żeby wprowadzić cię w temat, ale nic z tego nas nie dotyczy... na razie. Musimy się skupić na chwycie topora, ciężarze naszej zbroi i zapachu własnego potu, który spływa nam po czołach, kiedy walczymy z wrogami. Od tego zaczniemy.$B$B-Thran Khorman, nauczyciel wojowników ', 0),
(2446, 'koKR', 'Do: nowych adeptów sztuk tajemnych$BMasz obowiązek odszukać gnoma Marryka Nurribita i uczyć się pod jego kierunkiem, dopóki nie zostaniesz $gwezwany:wezwana; do pomocy swojemu ludowi w urządzeniu się w nowym miejscu zamieszkania. Bez obaw przygotuj się, proszę, na rygorystyczne procedury testowe i trudny proces aklimatyzacji, gdy będziesz szukać lokum i/lub jakiejkolwiek formy towarzystwa wśród miejscowych.$B$BPytania dotyczące twoich obowiązków i zdolności należy kierować do Marryka Nurribita.', 0),
(2450, 'koKR', 'UWAGA:$B$BZachowaj milczenie! Nie rozglądaj się! Ktoś może cię obserwować w tej właśnie chwili.$B$BNazywam się Alamar Grimm, $N. Szkolę tych, którzy pragną wiedzy i większej mocy z... innych światów. Poproszono mnie, żebym dyskretnie się z tobą skontaktował i przekazał, że mogę nauczyć cię prawdziwej magii.$B$BKiedy tylko zdołasz, znajdź mnie w głębi Kowadlina.$B$B-Alamar Grimm, nauczyciel czarnoksiężników ', 0),
(2455, 'koKR', 'Poskramiacz bestii, mistrz strzelectwa, sprawdzony tropiciel – czego jeszcze chcesz dokonać w tym życiu? Wszystko to razem wymaga sporo rozumu i mnóstwa cierpliwości.$B$BŚcieżka łowcy nie jest łatwa, to pewne. Czeka cię dużo szkolenia, jeśli chcesz być choć tak $gdobry:dobra; jak nasz najniższy rangą strzelec. Ale właśnie po to tu jestem.$B$BZnajdź mnie w Kowadlinie, z którego widać Dolinę Zimnej Grani. Będę czekał.$B$B-Thorgas Grimson, nauczyciel łowców ', 0),
(2464, 'koKR', 'Niektórzy boją się nas bardziej niż smoków. Niektórzy zazdroszczą nam bardziej niż najzdolniejszym kowalom. Niektórzy wychwalają naszą siłę w bitwie. Inni zachwycają się naszą wiarą. A niektórzy po prostu zazdroszczą, że potrafimy ich przepić pod stół! Ale wiedz jedno, $N: należysz do najznamienitszych obrońców w całym Azeroth. Święta Światłość daje nam siłę w tym samym stopniu, w jakim my umacniamy ją.$B$BPowiem ci więcej, kiedy trochę poznasz tę krainę. Znajdź mnie w Kowadlinie nad doliną.$B$B-Bromos Grummner, nauczyciel paladynów ', 0),
(2466, 'koKR', 'Kiedy Święta Światłość grzeje nam plecy, a każdego dnia dokonuje się nowych odkryć, bycie $gsynem:córką; Żelaznej Kuźni to ekscytująca sprawa. Liga Odkrywców każdego dnia robi postępy w poszukiwaniu dawno zapomnianych odpowiedzi na jeszcze starsze pytania. A teraz mamy wśród naszych wiernych także ciebie, byś $gpomógł:pomogła; w walce z troggami i każdym innym zagrożeniem dla naszych granic.$B$BZnajdź mnie, kiedy będziesz mieć czas. Będę w głębi Kowadlina, na wzgórzu. $B$B- Branstock Khalder, nauczyciel kapłanów ', 0);
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES
(4937, 'koKR', 'Ach, no proszę, ale z ciebie $gkrzepki gość:krzepka babka;! Może pomożesz mi w paru sprawach. Niewiele tu pomocnych rąk poza zielonymi uczniami, a ci mają swoje zmartwienia.', '', '', '', '', '', '', '', '', '', '', '', '', '', '', ''),
(50022, 'koKR', 'Witaj, $N! Piękny dzień na polowanie, prawda? Mnie samemu nieźle się ostatnio szczęści z dzikami. Może też chcesz spróbować?', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '');
