INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES
(6231, 0, 0, 'koKR', 'Nie ma żadnego poziomu z KROWAMI!... naprawdę! Powtarzam: nie ma poziomu z KROWAMI. No, może jest...'),
(6231, 0, 1, 'koKR', 'Nie ma za co, miłego dnia.'),
(6231, 0, 2, 'koKR', 'Prosimy o cierpliwość, wywołamy twoje imię, gdy przyjdzie twoja kolej. Pomagamy w kolejności, w jakiej zgłoszenia pojawiają się na naszym ekranie.'),
(6231, 0, 3, 'koKR', 'Ludzie myślą, że lubię hot dogi w cieście, ale tak naprawdę dostaję po nich niestrawności!!!'),
(6231, 0, 4, 'koKR', 'Techbot jest wrażliwy i takie słowa ranią mu uszy. :[ Bądź dla mnie $gmiły:miła;. Chcę tylko pomóc.'),
(6231, 0, 5, 'koKR', 'Jestem BOTEM. Mam mnóstwo informacji. Żeby się dowiedzieć, co wiem, napisz do mnie szeptem.'),
(6231, 0, 6, 'koKR', 'Kiedy konsultant z tobą rozmawia, każdą linijkę zaczyna od twojego imienia. Jeśli nie widzisz swojego imienia, nie mówi do ciebie.'),
(6231, 0, 7, 'koKR', 'Pamiętaj: jeśli będziesz nękać konsultanta albo spamować na kanale, twoje konto może zostać wyrzucone, zbanowane albo gorzej.'),
(6231, 0, 8, 'koKR', 'Jeśli cię wyciszono albo masz pytania o wyciszanie i przywracanie głosu, odwiedź...zzzzttt!!'),
(7800, 1, 1, 'koKR', 'Wybuchy! WIĘCEJ wybuchów! Muszę mieć więcej wybuchów!');
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText`, `FemaleText`, `VerifiedBuild`) VALUES
(125, 'koKR', 'Hej, Belm! Daj mi kufel piwa gromu i drugi dla $gmojego dobrego przyjaciela:mojej dobrej przyjaciółki;, $n.', '', 0),
(126, 'koKR', 'Jak tam pilnowanie beczek...?', '', 0),
(127, 'koKR', 'Ach, tego mi było trzeba! Chyba wezmę sobie jeszcze parę... popilnujesz mi tych beczek, $n?', '', 0),
(128, 'koKR', 'No, pora wracać do roboty. Ale miło było zrobić sobie krótką przerwę, a piwo gromu zawsze pije się z przyjemnością!', '', 0),
(159, 'koKR', '', 'Wracaj, Puszku!', 0),
(160, 'koKR', '', 'Czemu przede mną uciekasz, Puszku?!', 0),
(161, 'koKR', '', 'No chodź, Puszku! Chcę cię tylko wykąpać!', 0),
(162, 'koKR', '', 'Puszek! Puszku, przestań uciekać!', 0),
(164, 'koKR', '', 'Jak się zatrzymasz, dostaniesz marchewki codziennie przez cały rok!', 0),
(165, 'koKR', '', 'Nie każ mi wołać tatka, żeby cię złapał! On lubi łapać króliczki strzelbą!', 0),
(232, 'koKR', 'Hej, Kamień, słyszałeś o nowym silniku parowym, na którym jeździ stary Tonkrend?', '', 0),
(233, 'koKR', 'A tak. Słyszałem wszystko o tych nowych flargowanych wynalazkach. Zdjęli pancerz z obudowy, żeby zmniejszyć wagę. Bargh! Bzdura!', '', 0),
(234, 'koKR', 'Myślisz ty czasem o czymś innym niż walka? Na prostej zrobiłbym wokół ciebie kółko!', '', 0),
(235, 'koKR', 'Ba! Zanim podjechałbyś na zasięg starego Trollopługu, zostałaby z ciebie kupa gruzu!', '', 0),
(236, 'koKR', 'Argh! Jesteś beznadziejny!', '', 0),
(237, 'koKR', 'Hej, Fizzer, opowiadałem ci kiedyś, jak jechałem przez kanały, a jakieś gobliny w rozdrabniaczach próbowały urządzić na mnie zasadzkę?', '', 0),
(238, 'koKR', 'Ach, niech pomyślę. Tak, idę o zakład, że już chyba ze sto razy!', '', 0),
(239, 'koKR', 'Bruhaha! Te ich miny, kiedy działo starego Trollopługu obróciło się w ich stronę! Tymi swoimi piłami nawet mnie nie drasnęli!', '', 0),
(240, 'koKR', 'Ja bym po prostu wlał trochę „Wiecznego blasku” do zbiornika i był z powrotem w domu, zanim by się połapali, że mnie nie ma!', '', 0),
(241, 'koKR', 'Ba! Żadna w tym frajda!', '', 0),
(242, 'koKR', 'Hej, Kamień, wybierzmy się kiedyś na tor. Zrobimy parę okrążeń i zobaczymy, kto wygra?', '', 0),
(244, 'koKR', 'Jasne, byle zaraz potem ruszyć na arenę!', '', 0),
(245, 'koKR', 'Nic, co powiesz, nie zaciągnie mnie na arenę przeciwko temu monstrum, które nazywasz parowym czołgiem!', '', 0),
(246, 'koKR', 'Har! Boisz się, że uszkodzę twoją delikatną wyścigóweczkę?', '', 0),
(247, 'koKR', 'Ha! Bardziej się boję, że przez te stare dziury i rozdarcia to ustrojstwo pęknie i obsypie mnie odłamkami!', '', 0),
(248, 'koKR', 'Haha! Krzepki stary Trollopług ma ledwie kilka marnych blizn bitewnych!', '', 0),
(249, 'koKR', 'Nic nie przebije dźwięku dwugaźnikowego silnika parowego z widełkowym pierścieniem, który spala czysty kamień ognia!', '', 0),
(250, 'koKR', 'Ha! Ja tam zawsze wolę huk Kraterowego Działa XT, kiedy wystrzeliwuje pocisk!', '', 0),
(251, 'koKR', 'Ba! Nie poznałbyś świetnego silnika parowego, nawet gdyby walnął cię w łeb!', '', 0),
(252, 'koKR', 'Może i nie, ale gdyby walnął mnie w łeb, wiedziałbym dokładnie, z którego działa rozwalić go na najdrobniejsze kawałeczki!', '', 0),
(1883, 'koKR', 'Zamontuję tylko te żyromechaniczne zębatki i trybiki restabilizacyjne i odpalimy Rekombobulator.', '', 0),
(1884, 'koKR', 'To powinno załatwić sprawę.', '', 0),
(1885, 'koKR', 'Czas ocalić całą gnomią rasę. Raz kozie śmierć!', '', 0),
(1886, 'koKR', 'No, świetnie.', '', 0),
(1887, 'koKR', 'Wracamy do deski kreślarskiej.', '', 0),
(1888, 'koKR', 'Może trochę więcej smaru załatwi sprawę.', '', 0),
(1889, 'koKR', 'Tym razem było blisko. Chyba już prawie mamy.', '', 0),
(1890, 'koKR', 'Rekombobulator całkiem ładnie nabiera kształtów. Jeszcze tylko kilka poprawek!', '', 0),
(1891, 'koKR', 'Otóż to.', '', 0),
(1892, 'koKR', 'Dokładnie to samo myślę.', '', 0),
(1893, 'koKR', 'Sam bym tego lepiej nie ujął.', '', 0),
(1894, 'koKR', 'Zdecydowanie.', '', 0),
(1895, 'koKR', 'Myślałem dokładnie o tym samym.', '', 0),
(1908, 'koKR', 'Moja broń być spragniona!', 'Moja broń być spragniona!', 0),
(1909, 'koKR', 'Zabić ciebie być łatwo.', 'Zabić ciebie być łatwo.', 0),
(1910, 'koKR', 'Posmakuj magii Mroźnej Grzywy.', 'Posmakuj magii Mroźnej Grzywy.', 0),
(1911, 'koKR', 'Wy wszyscy chcieć tylko moje ziele.', 'Wy wszyscy chcieć tylko moje ziele.', 0),
(1912, 'koKR', 'Potnę cię!', 'Potnę cię!', 0),
(1913, 'koKR', 'Miażdżyć!', 'Miażdżyć!', 0),
(1914, 'koKR', 'Zabić!', 'Zabić!', 0),
(1915, 'koKR', 'Niszczyć!', 'Niszczyć!', 0),
(1917, 'koKR', 'Czas tłuc!', '', 0),
(1918, 'koKR', 'Śmiesz bezcześcić Warownię Mroźnych Grzyw? Szykuj się na śmierć!', '', 0),
(1919, 'koKR', 'Och, świetnie się dogadamy, $n.', '', 0),
(1934, 'koKR', 'Nigdy nie wchodź w drogę Czarnorytemu.', 'Nigdy nie wchodź w drogę Czarnorytemu.', 0),
(1935, 'koKR', 'Pora umierać.', 'Pora umierać.', 0),
(1936, 'koKR', 'Poczuj potęgę Czarnorytych!', 'Poczuj potęgę Czarnorytych!', 0),
(2281, 'koKR', 'Dziękuję ci, $Gchłopcze:dziewczyno;. Wielkie dzięki.', '', 0),
(2302, 'koKR', 'Bywaj, $n. I pamiętaj: wojownik nigdy nie odwraca się plecami do wroga!', '', 0),
(2351, 'koKR', 'Powodzenia, $n. I pamiętaj, odszukaj Muiredona, kiedy wykonasz zadanie.', '', 0),
(2422, 'koKR', 'Nie zostawimy żadnego gnoma.', 'Nie zostawimy żadnego gnoma.', 0),
(2423, 'koKR', 'Troggi... wciąż nadciągają. Giń, troggu! Giń!', 'Troggi... wciąż nadciągają. Giń, troggu! Giń!', 0),
(2424, 'koKR', 'Ta choroba mąci mi wzrok, ale wiem, że musisz być troggiem. Giń, plugawy najeźdźco!', 'Ta choroba mąci mi wzrok, ale wiem, że musisz być troggiem. Giń, plugawy najeźdźco!', 0),
(2425, 'koKR', 'Plugawy trogg, jakich mało. Giń!', 'Plugawy trogg, jakich mało. Giń!', 0),
(2435, 'koKR', 'W tych tematach mogę pomóc: | sterowniki | komendy | lag | boty... zzzttt!', '', 0),
(2437, 'koKR', 'Ja też cię kocham. :)', '', 0),
(2751, 'koKR', 'Żeby ten śnieg wreszcie cały stopniał. Ciągle moczy mi szatę i wszystko psuje!', '', 0),
(2753, 'koKR', 'Jaka wiadomość?', 'Jaka wiadomość?', 0),
(2774, 'koKR', 'Gdyby nie niepojęte, głupie szczęście goblinów, rozbijaliby swój bolid w każdym wyścigu!', 'Gdyby nie niepojęte, głupie szczęście goblinów, rozbijaliby swój bolid w każdym wyścigu!', 0),
(2775, 'koKR', 'Te wyścigi to świetna okazja, by pokazać naszą pomysłowość!', 'Te wyścigi to świetna okazja, by pokazać naszą pomysłowość!', 0),
(2776, 'koKR', 'W matrycowym regulometrze naszego bolidu siedzi nowe urządzenie. Powinno zwiększyć jego współczynnik prędkości co najmniej piętnastokrotnie!', 'W matrycowym regulometrze naszego bolidu siedzi nowe urządzenie. Powinno zwiększyć jego współczynnik prędkości co najmniej piętnastokrotnie!', 0),
(2777, 'koKR', 'Mój syn zaprojektowałby szybszy bolid niż ta toporna goblińska kupa złomu!', 'Mój syn zaprojektowałby szybszy bolid niż ta toporna goblińska kupa złomu!', 0),
(2778, 'koKR', 'Mój Gadżetyczny Almanakotron twierdzi, że powinniśmy pokonać gobliny o dwadzieścia sekund wyraźniej niż ostatnim razem!', 'Mój Gadżetyczny Almanakotron twierdzi, że powinniśmy pokonać gobliny o dwadzieścia sekund wyraźniej niż ostatnim razem!', 0),
(2779, 'koKR', 'Gdzie jest pomocnik Tirtha?', 'Gdzie jest pomocnik Tirtha?', 0),
(2780, 'koKR', 'Tirth ostatnio nie jest sobą, jego pomocnik zresztą też.', 'Tirth ostatnio nie jest sobą, jego pomocnik zresztą też.', 0),
(2781, 'koKR', 'Johnson? Chyba kręci się gdzieś w pobliżu...', 'Johnson? Chyba kręci się gdzieś w pobliżu...', 0),
(2826, 'koKR', 'Napełnij kufel i przysuń sobie krzesło. Mamy opowieści do snucia i beczułki do opróżnienia.', 'Napełnij kufel i przysuń sobie krzesło. Mamy opowieści do snucia i beczułki do opróżnienia.', 0),
(3121, 'koKR', 'Wezmę tylko z domu ogniskowacz zaklęć i zaczynamy!', '', 0),
(3122, 'koKR', 'Ba, nie ma go tu. Gdzie ja ostatnio miałem to przeklęte ustrojstwo?', '', 0),
(3123, 'koKR', 'No tak, leży przy łóżku. Heh, przepraszam!', '', 0),
(3124, 'koKR', 'No to świetnie! Naprawmy ci to.', '', 0),
(3125, 'koKR', 'Udało się! Hurra! Źródło mocy przywróciło naszyjnik!', '', 0),
(3131, 'koKR', '%s tryska krwią!', '%s tryska krwią!', 0),
(3367, 'koKR', '%s zostaje ochlapany krwią i ulega napromieniowaniu!', '%s zostaje ochlapany krwią i ulega napromieniowaniu!', 0),
(3829, 'koKR', 'Aaaaaach! Tak blisko ucieczki.', 'Aaaaaach! Tak blisko ucieczki.', 0),
(3881, 'koKR', 'Wyciągnij mnie stąd!', '', 0),
(3901, 'koKR', 'Witaj, $n! Jeśli czegoś nie ma w moim sklepie, całkiem możliwe, że mogę to zdobyć!', '', 0),
(3902, 'koKR', 'Witaj, Soviku, chcę obejrzeć twoje towary.', 'Witaj, Soviku, chcę obejrzeć twoje towary.', 0),
(3903, 'koKR', 'Wybierasz się do Gnomoregan, $n? To przyjdź ze mną porozmawiać!', '', 0),
(3904, 'koKR', 'Daj mi chwilę, skalibruję transponder do twojego wzrostu i wagi, $n.', '', 0),
(3905, 'koKR', 'Gotowe, $n, twój transponder działa!', '', 0),
(3928, 'koKR', '%s wiwatuje!', '', 0),
(3929, 'koKR', 'Dziękuję za ratunek! Wieść o twoim czynie nie przejdzie bez echa.', '', 0),
(3930, 'koKR', '%s macha wszystkim na pożegnanie.', '', 0),
(3948, 'koKR', 'Widzę wyjście! Szybko, szybko!', '', 0),
(3953, 'koKR', 'Oj, oj....', '', 0),
(3989, 'koKR', 'Brzzzzt!$B$BWitaj w matrycowym perforografie 3005 kreska A, terminalu o poziomie zabezpieczeń alfa.$B$BAby uzyskać dostęp do funkcji terminalu, musisz mieć białą kartę perforowaną.\n01000100 01101111 01110111 01101110 00100000 01110111 01101001 01110100 01101000 00100000 01110100 01101000 01100101 00100000 01101000 01101111 01110010 01100100 01100101 00100001', '', 0),
(4001, 'koKR', 'Pobierz kartę dostępu wyższego poziomu', 'Pobierz kartę dostępu wyższego poziomu', 0),
(4170, 'koKR', 'Brzzzzt!$B$BWitaj w matrycowym perforografie 3005 kreska A, terminalu o poziomie zabezpieczeń alfa.$B$BWykryto białą kartę perforowaną. Dostęp przyznany.\n01010100 01100101 01101100 01101100 00100000 01111001 01101111 01110101 01110010 00100000 01100110 01110010 01101001 01100101 01101110 01100100 01110011 00100000 01110100 01101111 00100000 01110000 01101100 01100001 01111001 00100000 01010111 01101111 01010111', '', 0),
(4376, 'koKR', 'Sprzedaję najlepsze stroje z tkaniny i skóry po tej stronie doliny!', '', 0),
(4377, 'koKR', 'Nie ma to jak parzący poranny napar w chłodny dzień w Dun Morogh, żeby dobrze zacząć!', '', 0),
(4378, 'koKR', 'Uuuuuu, gorące, gorące, gorące! Jeśli to nie doda ci wigoru, to już nie wiem co!', '', 0),
(4614, 'koKR', 'Eee, witaj! Jeśli chodzi o ściąganie należności i/lub wezwanie, to na pewno bierzesz mnie za kogoś innego. Strasznie przepraszam!', '', 0),
(4632, 'koKR', 'Witaj, $n! Jestem Scooty, mistrz inżynierii.', '', 0),
(4634, 'koKR', '$GZgubiłem:Zgubiłam; transponder i potrzebuję nowego, Scooty.', '$GZgubiłem:Zgubiłam; transponder i potrzebuję nowego, Scooty.', 0),
(4640, 'koKR', 'Witaj w Thelsamarze, twoim drugim domu w Loch Modan!$B$BThelsamar to miłe miejsce, ale kto odpowie na wezwanie do służby, nie zazna tu samego piwa i solonego mięsa! Jeśli nie boisz się stawić czoła niebezpieczeństwu w imię Przymierza, przeczytaj obwieszczenie przed thelsamarską siedzibą Ligi Odkrywców.', '', 0),
(5078, 'koKR', 'Bank Żelaznej Kuźni', 'Bank Żelaznej Kuźni', 0),
(5079, 'koKR', 'Masz jakieś nowe skarby, które chcesz trzymać w bezpiecznym miejscu? To zanieś je do Skarbca, do Kamiennopłaszczów.\nSkarbiec znajdziesz o rzut młotem na północny wschód od wejścia do Żelaznej Kuźni.', 'Masz jakieś nowe skarby, które chcesz trzymać w bezpiecznym miejscu? Zanieś je do Skarbca, do Kamiennopłaszczów. Skarbiec znajdziesz o rzut młotem na północny wschód od wejścia do Żelaznej Kuźni.', 0),
(5080, 'koKR', 'Bank? Och, chodzi ci o Skarbiec! Nie ma bezpieczniejszego miejsca na kosztowności niż Skarbiec. Znajdziesz go zaraz na północny wschód od wejścia do Żelaznej Kuźni.', 'Bank? Och, chodzi ci o Skarbiec! Nie ma bezpieczniejszego miejsca na kosztowności niż Skarbiec. Znajdziesz go zaraz na północny wschód od wejścia do Żelaznej Kuźni.', 0),
(5083, 'koKR', 'Chcesz się przelecieć na gryfie, co? W tej sprawie idź do Grytha Thurdena.\nZnajdziesz go po wschodniej stronie Wielkiej Kuźni, w samym środku Żelaznej Kuźni.', 'Chcesz się przelecieć na gryfie, co? W tej sprawie idź do Grytha Thurdena.\nZnajdziesz go po wschodniej stronie Wielkiej Kuźni, w samym środku Żelaznej Kuźni.', 0),
(5085, 'koKR', 'Ach, nie ma to jak przejażdżka na gryfie, co? Nocne elfy niech sobie zatrzymają te swoje hipo-coś-tam, a mnie dajcie gryfa i wiatr we włosach!\nNo, nie będę cię dłużej zatrzymywać. Idź do Grytha Thurdena po wschodniej stronie Wielkiej Kuźni, a on wyprawi cię w drogę.', 'Ach, nie ma to jak przejażdżka na gryfie, co? Nocne elfy niech sobie zatrzymają te swoje hipo-coś-tam, a mnie dajcie gryfa i wiatr we włosach!\nNo, nie będę cię dłużej zatrzymywać. Idź do Grytha Thurdena po wschodniej stronie Wielkiej Kuźni, a on wyprawi cię w drogę.', 0),
(5087, 'koKR', 'Jeśli myślisz o założeniu gildii, musisz to załatwić z Jondorem Stalobrwym w Punkcie informacyjnym Żelaznej Kuźni. Idź na południowy wschód od Wrót Żelaznej Kuźni, tam go znajdziesz.', 'Jeśli myślisz o założeniu gildii, musisz to załatwić z Jondorem Stalobrwym w Punkcie informacyjnym Żelaznej Kuźni. Idź na południowy wschód od Wrót Żelaznej Kuźni, tam go znajdziesz.', 0),
(5091, 'koKR', 'Karczma? Ach, chcesz wychylić kilka najlepszych piw, jakie ma do zaoferowania Żelazna Kuźnia? To idź do tawerny „Kamienny Ogień”.$B$BZnajdziesz ją po lewej stronie od wejścia do Żelaznej Kuźni, jeśli wchodzisz, albo po prawej, jeśli wychodzisz.', 'Karczma? Ach, chcesz wychylić kilka najlepszych piw, jakie ma do zaoferowania Żelazna Kuźnia? To idź do tawerny „Kamienny Ogień”.$B$BZnajdziesz ją po lewej stronie od wejścia do Żelaznej Kuźni, jeśli wchodzisz, albo po prawej, jeśli wychodzisz.', 0),
(5092, 'koKR', 'Jeśli szukasz karczmy, idź do tawerny „Kamienny Ogień”. Znajdziesz ją po lewej stronie od wejścia do Żelaznej Kuźni, jeśli wchodzisz, albo po prawej, jeśli wychodzisz.$B$BA, i jeśli idziesz w tamtą stronę, powiedz im, żeby mieli dla mnie gotowy kufel.', 'Jeśli szukasz karczmy, idź do tawerny „Kamienny Ogień”. Znajdziesz ją po lewej stronie od wejścia do Żelaznej Kuźni, jeśli wchodzisz, albo po prawej, jeśli wychodzisz.$B$BA, i jeśli idziesz w tamtą stronę, powiedz im, żeby mieli dla mnie gotowy kufel.', 0),
(5094, 'koKR', 'Skrzynkę pocztową znajdziesz tuż przy tawernie „Kamienny Ogień”. To zaraz na północ od Wrót Żelaznej Kuźni.', 'Skrzynkę pocztową znajdziesz tuż przy tawernie „Kamienny Ogień”. To zaraz na północ od Wrót Żelaznej Kuźni.', 0),
(5096, 'koKR', 'Parę dni temu w Sali Oręża Regnus Gromogranit przechwalał się nowym trofeum na ścianę. Jeśli chcesz się szkolić u wprawnego łowcy, idź do Regnusa.', 'Parę dni temu w Sali Oręża Regnus Gromogranit przechwalał się nowym trofeum na ścianę. Jeśli chcesz się szkolić u wprawnego łowcy, idź do Regnusa.', 0),
(5098, 'koKR', 'Ta mała czarodziejka, Bink, z Sali Tajemnic pewnie pomoże ci we wszystkich magicznych potrzebach.\nSala Tajemnic jest zaraz na północ od Wrót Żelaznej Kuźni.', 'Ta mała czarodziejka, Bink, z Sali Tajemnic pewnie pomoże ci we wszystkich magicznych potrzebach.\nSala Tajemnic jest zaraz na północ od Wrót Żelaznej Kuźni.', 0),
(5099, 'koKR', 'Szkolenie w sztukach magicznych na pewno znajdziesz w Sali Tajemnic, na północ od Wrót Żelaznej Kuźni. Juli Burzokocioł zawsze tam siedzi z nosem w książce.', 'Szkolenie w sztukach magicznych na pewno znajdziesz w Sali Tajemnic, na północ od Wrót Żelaznej Kuźni. Juli Burzokocioł zawsze tam siedzi z nosem w książce.', 0),
(5101, 'koKR', 'Ach, Braenna Krzemiograń. Ta to ma czarodziejskie ręce. W sprawach kapłańskich idź do Braenny.\nKieruj się na północ od Wrót Żelaznej Kuźni, do Sali Tajemnic. Tam ją znajdziesz.', 'Ach, Braenna Krzemiograń. Ta to ma czarodziejskie ręce. W sprawach kapłańskich idź do Braenny.\nKieruj się na północ od Wrót Żelaznej Kuźni, do Sali Tajemnic. Tam ją znajdziesz.', 0),
(5103, 'koKR', 'Tobie trzeba Brandura Żelaznomłota. Znajdziesz go w Sali Tajemnic na północ od Wrót Żelaznej Kuźni.', 'Tobie trzeba Brandura Żelaznomłota. Znajdziesz go w Sali Tajemnic na północ od Wrót Żelaznej Kuźni.', 0),
(5104, 'koKR', 'Ach, stary, dobry Brandur Żelaznomłot. Nie ma wątpliwości, że wskaże ci drogę, której szukasz, $gchłopcze:dziewczyno;. Znajdziesz go w Sali Tajemnic na północ od Wrót Żelaznej Kuźni.', 'Ach, stary, dobry Brandur Żelaznomłot. Nie ma wątpliwości, że wskaże ci drogę, której szukasz, $gchłopcze:dziewczyno;. Znajdziesz go w Sali Tajemnic na północ od Wrót Żelaznej Kuźni.', 0),
(5106, 'koKR', 'A po co ci usługi kogoś takiego? Dość mamy kłopotów z tym łotrzykiem, Hulfdanem Czarnobrodym, z Opuszczonej Pieczary. Mam i ciebie mieć na oku?', 'A po co ci usługi kogoś takiego? Dość mamy kłopotów z tym łotrzykiem, Hulfdanem Czarnobrodym, z Opuszczonej Pieczary. Mam i ciebie mieć na oku?', 0),
(5107, 'koKR', 'Całe to łotrzykowskie towarzystwo przesiaduje w Opuszczonej Pieczarze, na północ od Wrót Żelaznej Kuźni. Idę o zakład, że znajdziesz tam Fenthwicka, pewnie przy liczeniu monet z kolejnej obciętej sakiewki. Kiedyś go w końcu złapię!\nA tymczasem ciebie też będę mieć na oku, $gchłopcze:dziewczyno;.', 'Całe to łotrzykowskie towarzystwo przesiaduje w Opuszczonej Pieczarze, na północ od Wrót Żelaznej Kuźni. Idę o zakład, że znajdziesz tam Fenthwicka, pewnie przy liczeniu monet z kolejnej obciętej sakiewki. Kiedyś go w końcu złapię!\nA tymczasem ciebie też będę mieć na oku, $gchłopcze:dziewczyno;.', 0),
(5109, 'koKR', 'Gdzie lepiej szukać mrocznych ponuraków niż w mrocznej części Żelaznej Kuźni, trafnie nazwanej Opuszczoną Pieczarą? Tam na pewno znajdziesz Ostoserce, pewnie przy przyzywaniu jakiegoś plugastwa na swoje usługi.', 'Gdzie lepiej szukać mrocznych ponuraków niż w mrocznej części Żelaznej Kuźni, trafnie nazwanej Opuszczoną Pieczarą? Tam na pewno znajdziesz Ostoserce, pewnie przy przyzywaniu jakiegoś plugastwa na swoje usługi.', 0),
(5111, 'koKR', 'Och! Chcesz się szkolić na wojownika, co? Kelstrum Kamieniołamacz da ci niezły wycisk! Maszeruj do Sali Oręża na wschód od Wrót Żelaznej Kuźni.', 'Och! Chcesz się szkolić na wojownika, co? Kelstrum Kamieniołamacz da ci niezły wycisk! Maszeruj do Sali Oręża na wschód od Wrót Żelaznej Kuźni.', 0),
(5113, 'koKR', 'Jakiego nauczyciela profesji szukasz?', 'Jakiego nauczyciela profesji szukasz?', 0),
(5115, 'koKR', 'Potrzebujesz nauczyciela alchemii? A to się składa, akurat stamtąd wracam. Panią Jagodosyk znajdziesz w Majsterkowie, tam gdzie zbierają się gnomy.', 'Potrzebujesz nauczyciela alchemii? A to się składa, akurat stamtąd wracam. Panią Jagodosyk znajdziesz w Majsterkowie, tam gdzie zbierają się gnomy.', 0),
(5116, 'koKR', 'Szukasz nauczyciela alchemii, co? Akurat stamtąd wracam. Panią Jagodosyk znajdziesz w Majsterkowie, tam gdzie zbierają się gnomy.\n::westchnienie:: ...czemu, och, czemu nie padło na niebieską miksturę.', 'Szukasz nauczyciela alchemii, co? Akurat stamtąd wracam. Panią Jagodosyk znajdziesz w Majsterkowie, tam gdzie zbierają się gnomy.\n::westchnienie:: ...czemu, och, czemu nie padło na niebieską miksturę.', 0),
(5118, 'koKR', 'To właściwe miejsce, $gchłopcze:dziewczyno;! Ludzie przybywają tu z całego świata, żeby uczyć się kowalstwa. Bengusa Głębokucia znajdziesz przy kowadle w samym środku naszego pięknego miasta, tuż przy Wielkiej Kuźni.', 'To właściwe miejsce, $gchłopcze:dziewczyno;! Ludzie przybywają tu z całego świata, żeby uczyć się kowalstwa. Bengusa Głębokucia znajdziesz przy kowadle w samym środku naszego pięknego miasta, tuż przy Wielkiej Kuźni.', 0),
(5120, 'koKR', 'Nauczyciel gotowania, tak? No to idź do „Brązowego Kociołka” po północno-wschodniej stronie Wielkiej Kuźni. Daryl Riknussun nauczy cię przyrządzać wyborne danie, które na pewno postawi cię na nogi!', 'Nauczyciel gotowania, tak? No to idź do „Brązowego Kociołka” po północno-wschodniej stronie Wielkiej Kuźni. Daryl Riknussun nauczy cię przyrządzać wyborne danie, które na pewno postawi cię na nogi!', 0),
(5122, 'koKR', 'Ach, jeśli chcesz się uczyć fachu zaklinacza, potrzebny ci będzie Gimble Ostopuch. Znajdziesz go w jego sklepie, Pracowni magicznej Ostopuchów, tuż obok mistrza gryfów przy Wielkiej Kuźni.', 'Ach, jeśli chcesz się uczyć fachu zaklinacza, potrzebny ci będzie Gimble Ostopuch. Znajdziesz go w jego sklepie, Pracowni magicznej Ostopuchów, tuż obok mistrza gryfów przy Wielkiej Kuźni.', 0),
(5124, 'koKR', 'Chcesz się parać majsterkowaniem, tak? W takim razie musisz odwiedzić Sprężynka Syczotryba w Majsterkowie.\nIdź na wschód od Wrót Żelaznej Kuźni albo po prostu kieruj się odgłosem wybuchów.', 'Chcesz się parać majsterkowaniem, tak? W takim razie musisz odwiedzić Sprężynka Syczotryba w Majsterkowie.\nIdź na wschód od Wrót Żelaznej Kuźni albo po prostu kieruj się odgłosem wybuchów.', 0),
(5126, 'koKR', 'Cenna to umiejętność, ta pierwsza pomoc. Nasza miejscowa nauczycielka, Nissa Kamień Ognia, pokaże ci, jak to się robi. Szukaj jej po południowej stronie Wielkiej Kuźni, w gabinecie „Lekarz Żelaznej Kuźni”.', 'Cenna to umiejętność, ta pierwsza pomoc. Nasza miejscowa nauczycielka, Nissa Kamień Ognia, pokaże ci, jak to się robi. Szukaj jej po południowej stronie Wielkiej Kuźni, w gabinecie „Lekarz Żelaznej Kuźni”.', 0),
(5128, 'koKR', 'Grimnur Kamienne Piętno naopowiada ci niestworzonych historii o tej rybie, co mu uciekła, ale i tak jest jednym z najlepszych rybaków w okolicy. Ma w Opuszczonej Pieczarze sklep, który nazywa się „Wędrowny Rybak”.', 'Grimnur Kamienne Piętno naopowiada ci niestworzonych historii o tej rybie, co mu uciekła, ale i tak jest jednym z najlepszych rybaków w okolicy. Ma w Opuszczonej Pieczarze sklep, który nazywa się „Wędrowny Rybak”.', 0),
(5131, 'koKR', 'Kwiatki, nasionka i takie tam? To działka Reyny Kamiennej Gałęzi. Znajdziesz ją przy jej roślinach w gabinecie „Lekarz Żelaznej Kuźni” po południowej stronie Wielkiej Kuźni.', 'Kwiatki, nasionka i takie tam? To działka Reyny Kamiennej Gałęzi. Znajdziesz ją przy jej roślinach w gabinecie „Lekarz Żelaznej Kuźni” po południowej stronie Wielkiej Kuźni.', 0),
(5132, 'koKR', 'Och, chcesz się nauczyć zrywać stokrotki, co? Ha! Tylko się z tobą droczę, $gchłopaczku:dziewczyno;.\nTo porządna profesja, a Reyna Kamienna Gałąź pokaże ci, jak to się robi. Pracuje w gabinecie „Lekarz Żelaznej Kuźni” po południowej stronie Wielkiej Kuźni.', 'Och, chcesz się nauczyć zrywać stokrotki, co? Ha! Tylko się z tobą droczę, $gchłopaczku:dziewczyno;.\nTo porządna profesja, a Reyna Kamienna Gałąź pokaże ci, jak to się robi. Pracuje w gabinecie „Lekarz Żelaznej Kuźni” po południowej stronie Wielkiej Kuźni.', 0),
(5135, 'koKR', 'Fimble Cienkowrzeciono ma sklep po północno-zachodniej stronie Wielkiej Kuźni. Idę o zakład, że pokaże ci, jak robić porządne pancerze.', 'Fimble Cienkowrzeciono ma sklep po północno-zachodniej stronie Wielkiej Kuźni. Idę o zakład, że pokaże ci, jak robić porządne pancerze.', 0),
(5139, 'koKR', 'Czy mamy tu nauczycieli górnictwa? A gdzie ty niby jesteś!?\nJednego z najlepszych górników w całym Dun Morogh znajdziesz w pracowni „Górnictwo i Jubilerstwo Głębogóry” po północnej stronie Wielkiej Kuźni. Tam Geofram Głazopalec pokaże ci prawdziwą sztukę górnictwa.', 'Czy mamy tu nauczycieli górnictwa? A gdzie ty niby jesteś!?\nJednego z najlepszych górników w całym Dun Morogh znajdziesz w pracowni „Górnictwo i Jubilerstwo Głębogóry” po północnej stronie Wielkiej Kuźni. Tam Geofram Głazopalec pokaże ci prawdziwą sztukę górnictwa.', 0),
(5141, 'koKR', 'W sprawie skórowania idź do Balthusa Kamieniołupa. Jeśli coś da się oskórować, on cię nauczy jak. Przejdź się do sklepu Wyroby skórzane Cienkowrzecionów po północnej stronie Wielkiej Kuźni.', 'W sprawie skórowania idź do Balthusa Kamieniołupa. Jeśli coś da się oskórować, on cię nauczy jak. Przejdź się do sklepu Wyroby skórzane Cienkowrzecionów po północnej stronie Wielkiej Kuźni.', 0),
(5145, 'koKR', 'Ten Jormund Kamiennobrwy ma smykałkę do igły, oj ma. Jeśli potrzebujesz szkolenia, znajdziesz go w Pracowni krawieckiej Kamiennobrwych po północnej stronie Wielkiej Kuźni.', 'Ten Jormund Kamiennobrwy ma smykałkę do igły, oj ma. Jeśli potrzebujesz szkolenia, znajdziesz go w Pracowni krawieckiej Kamiennobrwych po północnej stronie Wielkiej Kuźni.', 0),
(5317, 'koKR', 'Gdzie jest dom aukcyjny? A tuż przy Wrotach Żelaznej Kuźni, zaraz jak się wchodzi do naszego pięknego miasta. Znajdziesz go naprzeciwko Skarbca.', 'Gdzie jest dom aukcyjny? A tuż przy Wrotach Żelaznej Kuźni, zaraz jak się wchodzi do naszego pięknego miasta. Znajdziesz go naprzeciwko Skarbca.', 0),
(5365, 'koKR', 'Och! Uważaj, co dajesz do zaklęcia, $gchłopcze:dziewczyno;. Mój kufel zaklęto tak, żeby nie uronił ani kropli, a teraz nie da się z niego pić! Co za tragedia.\nTylko pamiętaj o mojej radzie, kiedy zobaczysz Gimble\'a. Będzie w swoim sklepie tuż obok mistrza gryfów przy Wielkiej Kuźni.', 'Och! Uważaj, co dajesz do zaklęcia, $gchłopcze:dziewczyno;. Mój kufel zaklęto tak, żeby nie uronił ani kropli, a teraz nie da się z niego pić! Co za tragedia.\nTylko pamiętaj o mojej radzie, kiedy zobaczysz Gimble\'a. Będzie w swoim sklepie tuż obok mistrza gryfów przy Wielkiej Kuźni.', 0),
